// once we prepend our own, and a sign-off that collides with the signature.
// Both are deterministic to strip.
const SIGNOFFS = [
  'best regards', 'kind regards', 'warm regards', 'best wishes', 'regards',
  'best', 'thanks', 'thank you', 'cheers', 'sincerely', 'yours sincerely',
];

function stripGreeting(body, greeting) {
  let out = str(body);
  const g = str(greeting).replace(/[,\s]+$/, '');
  // The trailing comma or colon is REQUIRED: optional, this ate the start of any
  // body that merely began with "Hi" or "Hello".
  out = out.replace(/^\s*(hi|hello|hey|dear|greetings)\b[^\n,]{0,40}[,:]\s*\n?/i, '');
  if (g && out.toLowerCase().indexOf(g.toLowerCase()) === 0) {
    out = out.slice(g.length).replace(/^[,\s]+/, '');
  }
  return out.trim();
}

function stripSignoff(body) {
  const lines = str(body).split('\n');
  while (lines.length) {
    const last = lines[lines.length - 1].trim().toLowerCase().replace(/[,.!]+$/, '');
    if (!last) { lines.pop(); continue; }
    if (SIGNOFFS.indexOf(last) !== -1 || (lines.length > 1 && /^[a-z]{2,20}$/.test(last))) {
      lines.pop();
      continue;
    }
    break;
  }
  return lines.join('\n').trim();
}

// Paragraphs as the model wrote them, blank-line separated, inner whitespace
// tidied; never more than one blank line in a row.
function cleanText(raw, greeting) {
  return stripSignoff(stripGreeting(raw, greeting))
    .split(/\n\s*\n/)
    .map(function (p) { return p.replace(/\s*\n\s*/g, ' ').trim(); })
    .filter(Boolean)
    .join('\n\n');
}

function urlsIn(v) {
  return str(v).match(URL_RE) || [];
}

function bannedAdjectivesIn(v) {
  const t = ' ' + str(v).toLowerCase() + ' ';
  return BANNED_ADJECTIVES.filter(function (a) { return t.indexOf(a) !== -1; });
}

// Trial titles are quoted from ClinicalTrials.gov and can hold anything -- a
// digit, a question mark, a therapeutic area. The checks judge what the model
// wrote around a title, not the title it was given.
function withoutTitles(text, titles) {
  let out = str(text);
  for (const t of titles || []) {
    const title = str(t);
    if (!title) continue;
    let at = out.toLowerCase().indexOf(title.toLowerCase());
    while (at !== -1) {
      out = out.slice(0, at) + ' ' + out.slice(at + title.length);
      at = out.toLowerCase().indexOf(title.toLowerCase());
    }
  }
  return out;
}

function digitTokens(v) {
  return (str(v).match(/[\p{L}\p{N}]*\p{N}[\p{L}\p{N}]*/gu) || []).map(function (t) { return t.toLowerCase(); });
}

// Numbers the text states that the corpus (this lead's facts plus every claim it
// was offered) does not: a digit token, a spelled-out number or multiplier, or a
// percent sign.
function unlicensedNumbers(text, corpus) {
  const haveDigits = {};
  digitTokens(corpus).forEach(function (t) { haveDigits[t] = true; });
  const bad = digitTokens(text).filter(function (t) { return !haveDigits[t]; });
  let corpusWords = ' ' + fold(corpus).replace(/[^a-z0-9]+/g, ' ') + ' ';
  Object.keys(haveDigits).forEach(function (t) {
    if (/^\d+$/.test(t) && Number(t) < DIGIT_WORDS.length) corpusWords += DIGIT_WORDS[Number(t)] + ' ';
  });
  const textWords = fold(text).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean);
  textWords.forEach(function (w) {
    if (NUMBER_WORDS.indexOf(w) !== -1 && corpusWords.indexOf(' ' + w + ' ') === -1) bad.push(w);
  });
  if (str(text).indexOf('%') !== -1 && str(corpus).indexOf('%') === -1) bad.push('%');
  return bad;
}

function absentAreasNamed(text, absentAreas) {
  const plain = ' ' + fold(text).replace(/[^a-z0-9]+/g, ' ') + ' ';
  return (absentAreas || []).filter(function (a) {
    return plain.indexOf(' ' + fold(a).replace(/[^a-z0-9]+/g, ' ') + ' ') !== -1;
  });
}

// Does the text open on this name (or its first word)? Plain string compare.
function startsWithName(text, name) {
  const t = fold(text);
  const n = fold(name);
  if (!n) return false;
  const first = n.split(/\s+/)[0];
  const opensOn = function (w) {
    return t.indexOf(w) === 0 && (t.length === w.length || !/[a-z0-9]/.test(t.charAt(w.length)));
  };
  return opensOn(n) || (first.length >= 3 && opensOn(first));
}

function firstSentence(text) {
  const m = str(text).match(/^[\s\S]*?[.!?](?=\s|$)/);
  return m ? m[0] : str(text);
}

function countOf(re, text) {
  return (str(text).match(new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags)) || []).length;
}

// ---------------------------------------------------------------------------
// The rule checks. Each returns the tags it found; checkMessage runs them all.
// ---------------------------------------------------------------------------

// "Exactly one ask."
function askFlags(body, ask) {
  const flags = [];
  const q = countOf(/\?/, ask);
  if (!str(ask) || q === 0) flags.push('ask-none');
  if (q > 1 || REQUEST_IN_BODY.test(body)) flags.push('ask-multiple');
  if (ASK_SCHEDULING.test(ask)) flags.push('ask-scheduling');
  return flags;
}

// "The name appears at most once, in brackets." Stripping every bracketed
// segment leaves nothing that may still say the name.
function productFlags(text) {
  const flags = [];
  const name = new RegExp('\\b' + PRODUCT_NAME + '\\b', 'gi');
  const n = countOf(name, text);
  if (n > PRODUCT_NAME_MAX) flags.push('product-name-repeat');
  const unbracketed = str(text).replace(/\([^()]*\)/g, ' ');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(unbracketed)) flags.push('product-name-unbracketed');
  return flags;
}

// "The word 'AI' appears at most once ... Never 'AI-powered'."
function aiFlags(text) {
  const flags = [];
  if (countOf(/\bA\.?I\b\.?/, text) > AI_MAX) flags.push('ai-repeat');
  if (AI_POWERED.test(text)) flags.push('ai-powered');
  return flags;
}

function prospectSponsor(text) {
  return PROSPECT_SPONSOR.some(function (re) { return re.test(text); });
}

// Skill v3 section 3, Claims, forbidden.
function claimFlags(text, corpus) {
  const flags = [];
  if (GUARANTEE.test(text)) flags.push('claim-guarantee');
  if (unlicensedNumbers(text, corpus).length) flags.push('claim-number');
  if (VISITOR_ID.test(text)) flags.push('claim-visitor-id');
  const t = ' ' + fold(text) + ' ';
  if (NAMED_TOOLS.some(function (n) { return new RegExp('(^|[^a-z0-9])' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(t); })) {
    flags.push('claim-named-tool');
  }
  if (LANGUAGES.test(text)) flags.push('claim-language');
  if (CHATBOT.test(text)) flags.push('claim-chatbot');
  if (NOVA_BOOKS.test(text)) flags.push('claim-books');
  if (SOP_SOURCE.test(text)) flags.push('claim-sop');
  return flags;
}

// Skill v3 section 3, No repeats: "The description and the benefits must not
// repeat the same capability." Each description and benefit line names its
// capabilities (claims_library.capabilities, migration 013); two codes one
// message used that share one say the same thing twice. `capsOf(code)` returns
// a code's capabilities (none for an angle, proof or ask).
function repeatFlags(codes, capsOf) {
  const flags = [];
  const seen = {};
  let repeated = false;
  for (const code of codes || []) {
    for (const cap of capsOf(code) || []) {
      if (seen[cap] && seen[cap] !== code) repeated = true;
      seen[cap] = code;
    }
  }
  if (repeated) flags.push('claim-repeat');
  return flags;
}

// "Proof: one named live deployment, matched to the lead's geography."
function proofFlags(text, proofPool) {
  const flags = [];
  const pool = proofPool || [];
  const allowed = DEPLOYMENTS.filter(function (d) {
    return pool.some(function (p) { return fold(p.body).indexOf(fold(d)) !== -1; });
  });
  const both = pool.some(function (p) { return /\btwo CROs\b/i.test(p.body); });
  const named = DEPLOYMENTS.filter(function (d) { return fold(text).indexOf(fold(d)) !== -1; });
  if (named.some(function (d) { return allowed.indexOf(d) === -1; })) flags.push('proof-geo');
  const present = named.some(function (d) { return allowed.indexOf(d) !== -1; }) ||
    (both && /\btwo (?:CROs|CRO clients|clients)\b/i.test(text));
  if (!present) flags.push('proof-missing');
  return flags;
}

// The first sentence opens on the prospect fact. Section 9 Workflow 4:
// founder_name and city never open a message; a trial is never credited to
// their website.
function hookFlags(hook, src, titles) {
  const flags = [];
  if (startsWithName(hook, src.founder_name) || startsWithName(hook, src.city)) flags.push('hook-opener');
  const own = withoutTitles(hook, titles);
  const titlesNamed = (titles || []).filter(function (t) {
    return str(t) && hook.toLowerCase().indexOf(str(t).toLowerCase()) !== -1;
  }).length;
  const trialOnSite = SITE_CLAIM.test(own) && (titlesNamed > 0 || TRIAL_WORD.test(own));
  if (HOOK_SOURCE_OPENING.test(hook) || trialOnSite) flags.push('hook-source');
  return flags;
}

function linkFlags(text, week, approvedLink) {
  const flags = [];
  const urls = urlsIn(text);
  if (urls.length > MAX_URLS) flags.push('urls');
  if (urls.length && week <= LINK_FREE_WEEKS) flags.push('link-in-warmup');
  const approved = approvedLink ? urlsIn(approvedLink.body) : [];
  if (urls.some(function (u) { return approved.indexOf(u) === -1; })) flags.push('unapproved-link');
  if (urls.some(function (u) { return /linkedin\.com/i.test(u); })) flags.push('linkedin-link');
  if (urls.some(function (u) { return /\.pdf\b/i.test(u); })) flags.push('pdf-link');
  return flags;
}

function subjectFlags(subject, factCorpus, headcount, titles, absentAreas) {
  const flags = [];
  const chars = Array.from(subject).length;
  if (!subject || chars < SUBJECT_MIN_CHARS || chars > SUBJECT_MAX_CHARS) flags.push('subject');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(subject)) flags.push('subject-product');
  if (/\bA\.?I\b/i.test(subject)) flags.push('subject-ai');
  const prefix = new RegExp('\\b(' + SUBJECT_REPLY_PREFIXES.join('|') + ')\\s*:', 'i');
  if (prefix.test(subject)) flags.push('subject-reply');
  // "No capitals": sentence case. A capitalised word after the first is allowed
  // only when the facts spell it that way (a trial code, a city) or it is an
  // acronym a CRO uses.
  const corpusWords = {};
  (factCorpus.match(/[\p{L}\p{N}-]+/gu) || []).forEach(function (t) { corpusWords[t] = true; });
  const tokens = subject.match(/[\p{L}\p{N}-]+/gu) || [];
  const capped = tokens.filter(function (t, i) {
    if (!/\p{Lu}/u.test(t)) return false;
    if (i === 0 && !/^\p{Lu}{2,}$/u.test(t)) return false;
    return !corpusWords[t] && SUBJECT_ACRONYMS.indexOf(t.toUpperCase()) === -1;
  });
  if (capped.length) flags.push('subject-caps');
  const corpus = factCorpus + (headcount ? ' ' + headcount : '');
  const bare = withoutTitles(subject, titles);
  if (digitTokens(bare).some(function (t) { return digitTokens(corpus).indexOf(t) === -1; }) ||
      absentAreasNamed(bare, absentAreas).length) {
    flags.push('subject-ungrounded');
  }
  return flags;
}

// Sites and SMOs, 2026-10-09 (Section 9, Workflow 4; operator instruction).
// Vertex Clinical Research is a clinical research center and is never called a
// CRO, whoever the email is to (`vertex-cro`). And a research site or an SMO is
// never told about "CRO websites" (`cro-website`), never given the "two CROs"
// proof (`proof-two-cros`), and never called a CRO itself (`prospect-cro`) --
// "CROs choosing sites" is how a site hears from a CRO, so naming CROs as the
// site's visitors is allowed and is not tagged.
const VERTEX_AS_CRO = /\bVertex\b[^.?!]{0,60}\bCROs?\b|\bCROs?\b[^.?!]{0,30}\bVertex\b/i;
const CRO_WEBSITE = /\bCROs?(?:['’]s?)?\s+(?:web\s?)?sites?\b|\bCRO[- ]websites?\b/i;
const TWO_CROS = /\btwo CROs?\b/i;
const PROSPECT_CRO = /\b(?:you(?:['’]re| are)(?: a| an)?|your(?: own)?|as an?)\s+(?:small\s+|mid-sized\s+|independent\s+|local\s+)?CROs?\b/i;
function siteFlags(text, companyType) {
  const flags = [];
  if (VERTEX_AS_CRO.test(text)) flags.push('vertex-cro');
  if (companyType !== 'site' && companyType !== 'SMO') return flags;
  if (CRO_WEBSITE.test(text)) flags.push('cro-website');
  if (TWO_CROS.test(text)) flags.push('proof-two-cros');
  if (PROSPECT_CRO.test(text)) flags.push('prospect-cro');
  return flags;
}

// Every rule that applies to a message body, either channel.
function checkMessage(m) {
  let flags = [];
  if (!str(m.body)) flags.push('empty');
  if (words(m.core) > BODY_CEILING) flags.push('long');
  if (bannedAdjectivesIn(m.core).length) flags.push('adjective');
  if (MERGE_TAG.test(m.core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(m.body, m.ask));
  flags = flags.concat(productFlags(m.core));
  flags = flags.concat(aiFlags(m.core));
  if (prospectSponsor(m.core)) flags.push('prospect-sponsor');
  const own = withoutTitles(m.core, m.titles);
  flags = flags.concat(claimFlags(own, m.corpus));
  if (absentAreasNamed(own, m.absentAreas).length) flags.push('ungrounded-area');
  if (str(m.body)) flags = flags.concat(hookFlags(firstSentence(m.body), m.src, m.titles));
  flags = flags.concat(proofFlags(m.core, m.proofPool));
  flags = flags.concat(siteFlags(m.core, m.companyType));
  return flags;
}

function unique(list) {
  return list.filter(function (v, i) { return list.indexOf(v) === i; });
}

// Word-set overlap, for attributing an ask the model did not code to the library
// line it paraphrased. Also used by the follow-ups (Workflow 6), which embed
// everything above "Node body" verbatim.
function wordSet(v) {
  const set = {};
  fold(v).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean).forEach(function (w) { set[w] = true; });
  return set;
}
function jaccard(a, b) {
  const A = wordSet(a);
  const B = wordSet(b);
  const keys = unique(Object.keys(A).concat(Object.keys(B)));
  const both = keys.filter(function (k) { return A[k] && B[k]; }).length;
  return keys.length ? both / keys.length : 0;
}

// ---------------------------------------------------------------------------

// ===========================================================================
// Assemble Follow-Up -- n8n Code node (Run Once for Each Item).
//
// build_workflow.py ships this node as drafting's code_assemble.js -- every
// line above its "Node body" marker, verbatim -- followed by this file. So a
// follow-up is checked by the first touch's own rule functions (askFlags,
// claimFlags, productFlags, aiFlags, repeatFlags, ...), not by a copy that
// could drift from them: drafting skill v3 section 8, "composed by the drafting
// model under every rule above".
//
// What this adds is the follow-up's own rules (skill section 8):
//
//   length     #1 is 40-70 words, #2 at most 40 (body plus ask)
//   new claim  #1 adds exactly one angle or benefit the first email did not use
//              (`fu-no-new-claim`, `fu-repeat`); #2 adds none (`fu-new-claim`)
//   frame      greeting, opt-out, signature and the quoted first email are
//              appended here, never generated -- the same frame the send path
//              checks every follow-up for
//
// A violation tags `variant` rather than discarding the draft, as in Workflow
// 4: the reviewer sees the tag next to the text. A failed call writes nothing,
// and the lead is due again on the next run (skill section 6: no fallback).
// ===========================================================================

// Skill v3 section 8, parsed from the skill at build time.
const FOLLOW_UP_1_MIN = 40;
const FOLLOW_UP_1_MAX = 70;
const FOLLOW_UP_2_MAX = 40;

const SIGNATURE = "Abdullah Amir\nFounder, Amitrix Labs\n+923178485713";
const SENDER_NAME = "Abdullah Amir";

const src = $('Build Follow-Up').item.json;
const resp = $input.item.json;
const n = Number(src.follow_up);

function failed(detail) {
  return {
    json: {
      lead_id: src.lead_id,
      write: false,
      skip_reason: 'Claude follow-up call did not answer usably: ' + detail,
      usage: resp && resp.usage ? resp.usage : null,
    },
  };
}

if (!resp || typeof resp !== 'object') return failed('no response item');
if (resp.error) {
  const e = resp.error;
  return failed((typeof e === 'string' ? e : JSON.stringify(e)).slice(0, 300));
}
if (resp.stop_reason !== 'end_turn') {
  const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
  return failed('stop_reason ' + JSON.stringify(resp.stop_reason) + why);
}
const text = (Array.isArray(resp.content) ? resp.content : [])
  .filter(function (b) { return b && b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('');
let parsed = null;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}
const FU_FIELDS = ['body', 'ask', 'added_claim'];
const FU_LISTS = ['claims', 'first_email_covers'];
if (!parsed || typeof parsed !== 'object' ||
    FU_FIELDS.some(function (f) { return typeof parsed[f] !== 'string'; }) ||
    FU_LISTS.some(function (f) { return !Array.isArray(parsed[f]); })) {
  return failed('response text was not the follow-up schema: ' + text.slice(0, 200));
}

// --- The claims this note used ------------------------------------------------

const pools = src.library_pools || {};
const offered = {};
SLOT_ORDER.forEach(function (slot) {
  (pools[slot] || []).forEach(function (l) {
    offered[l.code] = { slot: slot, confirmed: l.confirmed, capabilities: l.capabilities || [] };
  });
});

const body = cleanText(parsed.body, src.greeting);
const ask = cleanText(parsed.ask, src.greeting);
const core = [body, ask].filter(Boolean).join('\n\n');

// Reported codes, checked against what this note was offered. As in Workflow 4,
// an ask or proof the model left uncoded is attributed from the text -- never
// rely on a model to copy an identifier.
const reported = unique(parsed.claims.map(str).filter(Boolean));
const unknown = reported.filter(function (c) { return !offered[c]; });
const added = str(parsed.added_claim);
let used = reported.filter(function (c) { return offered[c]; });
if (added && offered[added] && used.indexOf(added) === -1) used.push(added);
if (!used.some(function (c) { return offered[c].slot === 'ask'; })) {
  let best = null;
  (pools.ask || []).forEach(function (l) {
    const j = jaccard(ask, l.body);
    if (j >= 0.5 && (!best || j > best.j)) best = { code: l.code, j: j };
  });
  if (best) used.push(best.code);
}
if (!used.some(function (c) { return offered[c].slot === 'proof'; })) {
  (pools.proof || []).forEach(function (l) {
    const names = DEPLOYMENTS.filter(function (d) { return fold(l.body).indexOf(fold(d)) !== -1; });
    if (names.some(function (d) { return fold(core).indexOf(fold(d)) !== -1; }) && used.indexOf(l.code) === -1) used.push(l.code);
  });
}
used = used.sort(function (a, b) { return SLOT_ORDER.indexOf(offered[a].slot) - SLOT_ORDER.indexOf(offered[b].slot); });
const covers = parsed.first_email_covers.map(str).filter(Boolean);

// --- The checks ------------------------------------------------------------------

function followUpFlags() {
  let flags = [];
  const wc = words(core);
  if (!body) flags.push('empty');
  if (n === 1 && wc > FOLLOW_UP_1_MAX) flags.push('long');
  if (n === 1 && wc < FOLLOW_UP_1_MIN) flags.push('short');
  if (n === 2 && wc > FOLLOW_UP_2_MAX) flags.push('long');
  if (bannedAdjectivesIn(core).length) flags.push('adjective');
  if (MERGE_TAG.test(core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(body, ask));
  flags = flags.concat(productFlags(core));
  flags = flags.concat(aiFlags(core));
  if (prospectSponsor(core)) flags.push('prospect-sponsor');
  // Sites and SMOs (2026-10-09): never "CRO websites", "two CROs" or the
  // prospect called a CRO; Vertex never called a CRO for anyone.
  flags = flags.concat(siteFlags(core, src.company_type));
  flags = flags.concat(claimFlags(core, src.corpus));
  if (absentAreasNamed(core, src.absent_areas).length) flags.push('ungrounded-area');
  // A follow-up need not name a deployment, but one it names must be this
  // lead's (proof-geo). No link is approved for a follow-up at all.
  flags = flags.concat(proofFlags(core, pools.proof).filter(function (f) { return f === 'proof-geo'; }));
  flags = flags.concat(linkFlags(core, LINK_FREE_WEEKS + 1, null));
  if (unknown.length || !reported.length) flags.push('claim-code');
  flags = flags.concat(repeatFlags(used, function (c) { return offered[c].capabilities; }));
  // Skill section 8: #1 adds exactly one angle or benefit the first email did
  // not use; #2 adds none.
  if (n === 1) {
    const newOnes = used.filter(function (c) { return ['angle', 'benefit'].indexOf(offered[c].slot) !== -1; });
    if (!added || !offered[added] || ['angle', 'benefit'].indexOf(offered[added].slot) === -1 || newOnes.length !== 1) {
      flags.push('fu-no-new-claim');
    }
    if (added && ((src.first_codes || []).indexOf(added) !== -1 || covers.indexOf(added) !== -1)) flags.push('fu-repeat');
  }
  if (n === 2 && (added || used.some(function (c) { return ['angle', 'benefit'].indexOf(offered[c].slot) !== -1; }))) {
    flags.push('fu-new-claim');
  }
  if (used.some(function (c) { return !offered[c].confirmed; })) flags.push('unconfirmed-claim');
  return unique(flags);
}

const flags = followUpFlags();

// --- The sendable text -----------------------------------------------------------
//
// Greeting / note / ask / opt-out / signature, then the first email quoted. The
// opt-out-then-signature tail is exactly what Workflow 6's send path checks for.

const firstBody = String(src.first_body || '').replace(/\r\n?/g, '\n').trim();
const sent = new Date(src.first_sent_at);
const when = isNaN(sent.getTime()) ? 'earlier' : sent.toUTCString().slice(0, 16);
const quoted = firstBody.split('\n').map(function (ln) { return ln ? '> ' + ln : '>'; }).join('\n');
const full = [
  src.greeting,
  '',
  core,
  '',
  OPT_OUT,
  '',
  SIGNATURE,
  '',
  'On ' + when + ', ' + SENDER_NAME + ' wrote:',
  quoted,
].join('\n');

const variant = 'follow-up-' + n + '/' + used.join('.') + (flags.length ? '+' + flags.join(',') : '');

return {
  json: {
    lead_id: src.lead_id,
    write: true,
    follow_up: n,
    flags: flags,
    words: words(core),
    claims: used,
    first_email_covers: covers,
    model: resp.model,
    usage: resp.usage || null,
    // Auto-approval (migration 014): what the shared Approval Gate and the claim
    // check need. Only the note itself is checked -- not the subject (Re: + the
    // subject already sent) and not the quoted first email, which went out.
    approval: {
      kind: 'follow-up',
      auto_approve: src.auto_approve === true,
      country: src.country,
      record: src.prospect_record,
      claims: src.check_claims,
      first_email: src.first_core,
      check: { subject: null, text: core },
      repair_fields: ['body', 'ask'],
    },
    // The repair loop edits the model's answer and runs it through a second
    // copy of this node; `repair` (set by Apply Repair) carries the attempts.
    composition: parsed,
    repair: resp.repair || null,
    payload: {
      lead_id: src.lead_id,
      action: 'draft-follow-up',
      draft: {
        channel: 'email',
        variant: variant,
        subject: 'Re: ' + str(src.first_subject).replace(/^(?:re:\s*)+/i, ''),
        body: full,
      },
    },
  },
};

// ===========================================================================
// Approval Gate -- n8n Code node (Run Once for Each Item).
//
// Auto-approval of email drafts (migration 014), shared by Workflow 4
// (Drafting) and Workflow 6 (Follow-Ups): both builds embed this file, and
// code_approval_apply.js after everything above this file's "Node body" marker,
// so the two workflows judge a draft with the same functions.
//
// An email draft -- first touch or follow-up -- is approved by the workflow
// that wrote it only if ALL of these hold:
//
//   1. settings.auto_approve_email is on          (read at runtime, migration 014)
//   2. it carries no rule tag                     (nothing after '+' in variant)
//   3. it is not a low-context note, nor a no-send-clock note
//   3b. its lead's country has a Send business-hours clock (Section 12)
//   4. every claim code it records is confirmed   (claims_library.confirmed)
//   5. a second Sonnet 5.5 call compares each product claim with the confirmed
//      claims and each prospect fact with the enrichment record, and every one
//      is supported. A widened claim is a failure.
//
// 1-4 are deterministic and decided HERE, before any money is spent: a draft
// that fails one is held, and the model is not called. 5 is the Claude Claim
// Check node; Apply Claim Check (code_approval_apply.js) reads its answer.
// A LinkedIn draft is never auto-approved (Section 6) and never checked.
//
// A held draft is written 'pending' with hold_reason saying why. The database
// re-checks 1-4 itself (migration 014's drafts_approval_rules) and turns an
// auto-approval that breaks one into a hold, so a bug here can make the
// workflow approve less, never more.
//
// THE REPAIR LOOP (2026-10-03). When 5 holds an email for a widened or
// unsupported statement, the drafting model is sent the email and the
// checker's exact reasons and rewrites only the flagged sentences
// (code_approval_apply.js builds that request; code_approval_repair.js
// applies the rewrites -- by code, so nothing else in the email can change).
// The repaired composition then runs through a second copy of the Assemble
// node (every rule again, the same code), this gate, and the claim check
// again. At most MAX_REPAIRS repairs; the workflows unroll exactly that many
// rounds. Nothing about rules 1-5 is relaxed: a repair is one more chance to
// pass the same checks. A draft is HELD for a claim-check failure only after
// the repairs, and hold_reason then lists every attempt's reasons.
//
// The item this node reads carries `payload` (the drafts Write will insert --
// `payload.drafts` in Workflow 4, `payload.draft` in Follow-Ups) and
// `approval`, the context its Assemble node built:
//
//   approval.kind          'first-touch' | 'follow-up'
//   approval.auto_approve  settings.auto_approve_email, as the batch query read it
//   approval.record        the prospect record: the facts the draft may state
//   approval.claims        [{code, slot, body, confirmed}] -- the lines it may use
//   approval.first_email   the first email as sent (follow-ups only), context
//   approval.check         {subject, text}: the generated text the email carries
//   approval.repair_fields the composition fields that text came from
//
// plus `composition` (the model's parsed answer, which a repair edits) and,
// after a repair, `repair` (the attempts so far, for the record).
//
// A low-context item (Workflow 4's other branch) has no `approval`; its drafts
// are held for what they are.
// ===========================================================================

// Section 3: the claim check is a second call to the drafting model, with the
// drafting node's request parameters -- no temperature/top_p (a 400 on this
// model), adaptive thinking by default, effort set explicitly, JSON through
// output_config.format with a strict schema. Both builds assert these against
// the Master Ref.
const CHECK_MODEL = 'claude-sonnet-5-5';
const CHECK_EFFORT = 'high';
const CHECK_MAX_TOKENS = 16000;

// Section 12's business-hours clocks, as a list of country names, substituted
// at build time from the doc's own table by whichever generator embeds this
// file -- the same table code_decide.js's COUNTRY_CLOCKS is checked against.
//
// Rule 3b. Send refuses an email to a country with no clock for ever
// (`unknown-country`), so approving one would put a draft in the digest's
// auto-approved list that can never go out, and pay for a claim check to get
// there. Assess Grounding already stops such a lead before the drafting call;
// this is the gate's own copy of that rule, because a follow-up, a redraft
// under an older build, or a country removed from the table later would all
// reach here without passing through that branch.
const SEND_CLOCK_COUNTRIES = ["Albania", "Algeria", "Angola", "Argentina", "Armenia", "Australia", "Austria", "Azerbaijan", "Bahamas", "Bahrain", "Bangladesh", "Belgium", "Benin", "Bosnia and Herzegovina", "Brazil", "Bulgaria", "Burkina Faso", "Burundi", "Cambodia", "Cameroon", "Canada", "Chile", "China", "Colombia", "Congo", "Costa Rica", "Cote d'Ivoire", "Croatia", "Cyprus", "Czech Republic", "DR Congo", "Denmark", "Djibouti", "Dominican Republic", "Ecuador", "Egypt", "El Salvador", "Equatorial Guinea", "Estonia", "Ethiopia", "Finland", "France", "Gabon", "Gambia", "Georgia", "Germany", "Ghana", "Greece", "Guatemala", "Guinea", "Hong Kong", "Hungary", "India", "Indonesia", "Ireland", "Israel", "Italy", "Jamaica", "Japan", "Jordan", "Kazakhstan", "Kenya", "Kosovo", "Kuwait", "Kyrgyzstan", "Latvia", "Lebanon", "Liberia", "Lithuania", "Luxembourg", "Macedonia", "Madagascar", "Malawi", "Malaysia", "Mali", "Malta", "Mauritania", "Mauritius", "Mexico", "Moldova", "Mongolia", "Montenegro", "Morocco", "Mozambique", "Nepal", "Netherlands", "New Zealand", "Nigeria", "Norway", "Oman", "Pakistan", "Panama", "Papua New Guinea", "Paraguay", "Peru", "Philippines", "Poland", "Portugal", "Qatar", "Romania", "Rwanda", "Saint Lucia", "Saudi Arabia", "Senegal", "Serbia", "Singapore", "Slovakia", "Slovenia", "South Africa", "South Korea", "Spain", "Sri Lanka", "Suriname", "Sweden", "Switzerland", "Taiwan", "Tanzania", "Thailand", "Togo", "Trinidad and Tobago", "Tunisia", "Turkey", "Turkmenistan", "UAE", "USA", "Uganda", "Ukraine", "United Kingdom", "Uruguay", "Uzbekistan", "Vietnam", "Zambia", "Zimbabwe"];

// One entry per statement, in the email's order. Every object closes with
// additionalProperties:false, which structured outputs requires.
const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    statements: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          sentence: { type: 'string' },
          statement: { type: 'string' },
          kind: { type: 'string', enum: ['claim', 'prospect', 'none'] },
          source: { type: 'string' },
          why: { type: 'string' },
          verdict: { type: 'string', enum: ['supported', 'widened', 'unsupported', 'joined', 'none'] },
        },
        required: ['sentence', 'statement', 'kind', 'source', 'why', 'verdict'],
        additionalProperties: false,
      },
    },
  },
  required: ['statements'],
  additionalProperties: false,
};

// The worked example of a widening is deliberately NOT draft 99's sentence
// ("..., so you know exactly what came in."): that one is the held-out case the
// dry run proves the check catches, and a check shown its own test case proves
// nothing.
const CHECK_SYSTEM_PROMPT = [
  'You check one outbound sales email before it is sent with no human review. A small company',
  'sells a website assistant to contract research organisations (CROs). Your only job is to find',
  'any statement in the email that says more than its sources support.',
  '',
  'You are given:',
  '- APPROVED CLAIMS: the only things the email may say about what we built, what it does, the',
  '  problem it addresses, who uses it, and the offer. Each has a code. The email may rephrase a',
  '  claim; it may never widen one.',
  '- PROSPECT RECORD: the only facts known about the recipient. A fact may say what it does NOT',
  '  establish; that limit is part of the fact.',
  '- Sometimes THE FIRST EMAIL we already sent them, as context. It is not evidence.',
  '- THE EMAIL TO CHECK. Its greeting, opt-out line and signature are fixed text and are not shown.',
  '',
  'Work through the email one sentence at a time, in order. The subject line, when given, counts',
  'as a sentence. Copy each sentence into "sentence" exactly as it appears. A sentence that makes',
  'several statements gets one entry per statement, each with the same "sentence" and its own',
  '"statement" (the words of the sentence that make that statement).',
  '',
  'Classify each statement:',
  '- "claim": anything about what we built, what it does or will do for them, the problem it',
  '  addresses, who uses it, or the offer (the demo).',
  '- "prospect": anything about the recipient -- their company, people, trials, work or website.',
  '- "none": a question that only asks, a reference back to our earlier email that adds nothing',
  '  new, or wording that asserts nothing.',
  'Words an approved claim itself uses about "you" -- your website, your team, your working',
  'hours -- belong to that claim. Judge them as part of the claim, not as prospect facts.',
  'The product\'s name in brackets, "(we call it Nova)", only names what the sentence describes:',
  'it is "none", not a claim. Judge the rest of that sentence as usual.',
  '',
  'Judge each statement:',
  '- claim: "supported" when an approved claim says the same thing or more -- rephrasing,',
  '  shortening and reordering are fine. "widened" when it rests on an approved claim but says',
  '  more: a broader scope, a stronger degree, a certainty or completeness the claim does not',
  '  state, or an added outcome, consequence or capability. "unsupported" when no approved claim',
  '  makes it.',
  '- prospect: "supported" when the record states it. "joined" when it links facts the record',
  '  keeps separate (a trial "in" their city, an area "of" a trial). "unsupported" when the record',
  '  does not state it.',
  '- none: "none".',
  '',
  'An example of widened, for a different claim. Approved: "It sends your capabilities deck the',
  'moment a sponsor asks for it." Email: "It sends your capabilities deck the moment a sponsor',
  'asks, so no request ever goes unanswered." The added clause claims an outcome -- every',
  'request answered -- that the approved claim does not make.',
  '',
  'When you are unsure whether a statement says more than its source, judge it widened or',
  'unsupported: a held email costs a person a minute, and a widened claim sent costs trust.',
  'Do not judge tone, length or style -- only whether each statement is supported.',
  '',
  'For every claim and prospect statement, "source" is the code of the approved claim, or the',
  'number of the record fact, you compared it with ("" when there is none). "why" is one short',
  'sentence.',
].join('\n');

const KINDS = ['claim', 'prospect', 'none'];
const VERDICTS = ['supported', 'widened', 'unsupported', 'joined', 'none'];

function apStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function apFold(v) {
  return apStr(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// The words of a text, for comparing what the checker quoted with what the
// email says: case, accents, punctuation and typographic quotes all fold away.
function apWords(v) {
  return apFold(v).replace(/[^a-z0-9]+/g, ' ').trim();
}

function excerpt(v, n) {
  const t = apStr(v).replace(/\s+/g, ' ');
  const max = n || 90;
  return t.length > max ? t.slice(0, max - 1) + '…' : t;
}

// 'unnamed/D2.ANG-HOURS.BEN-SEE.PR-BOTH.A1+long,claim-repeat'
//   -> codes ['D2','ANG-HOURS','BEN-SEE','PR-BOTH','A1'], tags ['long','claim-repeat']
function variantCodes(variant) {
  const v = apStr(variant);
  const slash = v.indexOf('/');
  return slash === -1 ? [] : v.slice(slash + 1).split('+')[0].split('.').map(apStr).filter(Boolean);
}

function variantTags(variant) {
  const v = apStr(variant);
  const plus = v.indexOf('+');
  return plus === -1 ? [] : v.slice(plus + 1).split(/[,+]/).map(apStr).filter(Boolean);
}

function isLowContext(variant) {
  return /^low-context(\/|$)/.test(apStr(variant));
}

// The other no-model branch (2026-10-07): a lead whose country has no Send
// business-hours clock. Its own prefix, so a reviewer is not told "low context"
// about a lead whose facts were fine.
function isNoSendClock(variant) {
  return /^no-send-clock(\/|$)/.test(apStr(variant));
}

// Section 12's clock table, case-insensitively -- the same way code_decide.js
// looks it up, so the gate and Send can never disagree about one lead.
const SEND_CLOCK_KEYS = SEND_CLOCK_COUNTRIES.map(function (c) { return String(c).toLowerCase(); });

function hasSendClock(country) {
  return SEND_CLOCK_KEYS.indexOf(apStr(country).toLowerCase()) !== -1;
}

// The drafts an item carries, whichever workflow built it.
function draftsOf(payload) {
  if (!payload || typeof payload !== 'object') return [];
  if (Array.isArray(payload.drafts)) return payload.drafts;
  return payload.draft && typeof payload.draft === 'object' ? [payload.draft] : [];
}

function confirmedCodes(ctx) {
  return ((ctx && ctx.claims) || []).filter(function (c) { return c && c.confirmed === true; })
    .map(function (c) { return apStr(c.code); });
}

// Rules 1-4 and the channel rule. Every reason that applies, in this order, so
// the digest and the reviewer see all of them -- not just the first.
function gateReasons(draft, ctx) {
  const reasons = [];
  const variant = apStr(draft && draft.variant);
  if (!draft || draft.channel !== 'email') {
    reasons.push('linkedin: always reviewed and sent by hand');
    return reasons;
  }
  if (isLowContext(variant)) {
    reasons.push('low-context: a note to a person, not an email to send');
    return reasons;
  }
  if (isNoSendClock(variant)) {
    reasons.push('no-send-clock: a note to a person, not an email to send');
    return reasons;
  }
  if (!ctx || typeof ctx !== 'object') {
    reasons.push('no-context: the draft arrived without its approval context');
    return reasons;
  }
  const country = apStr(ctx.country);
  if (!hasSendClock(country)) {
    // Held, not repaired and never checked: no rewrite can give a country a
    // business-hours clock, and Send would refuse the email anyway.
    reasons.push('no-send-clock: ' + (country || '(no country)') +
      ' has no business-hours clock, so this email can never be sent (Section 12)');
    return reasons;
  }
  if (ctx.auto_approve !== true) reasons.push('auto-approve-off: settings.auto_approve_email is false');
  const tags = variantTags(variant);
  if (tags.length) reasons.push('rule-tags: ' + tags.join(', '));
  const codes = variantCodes(variant);
  if (!codes.length) {
    reasons.push('no-claims: the draft records no claim codes');
  } else {
    const ok = confirmedCodes(ctx);
    const bad = codes.filter(function (c) { return ok.indexOf(c) === -1; });
    if (bad.length) reasons.push('unconfirmed-claim: ' + bad.join(', '));
  }
  if (!apStr(ctx.check && ctx.check.text)) reasons.push('no-context: no generated text to check');
  return reasons;
}

function checkText(check) {
  const subject = apStr(check && check.subject);
  return (subject ? subject + '\n' : '') + apStr(check && check.text);
}

function checkPrompt(ctx) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const followUp = ctx.kind === 'follow-up';
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = [
    'APPROVED CLAIMS:',
  ].concat(claims.map(function (c) { return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body); }), [
    '',
    'PROSPECT RECORD:',
    apStr(ctx.record) || '(nothing is known about them)',
  ]);
  if (followUp && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only, not evidence:', '---',
      apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL TO CHECK (' + (followUp ? 'a follow-up to the first email' : 'a first email') + '):');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '',
    'Check every sentence' + (subject ? ', the subject line included' : '') + ', in order.');
  return out.join('\n');
}

// PROMPT CACHING -- on since 2026-10-08 for the claim check, off for the repair.
// The reasoning and the measurements are in code_assess.js's comment; what is
// specific to these two call sites:
//
//   * CHECK_SYSTEM_PROMPT is 1,080 tokens, over Sonnet 5.5's 512-token minimum
//     cacheable prefix (live docs, 2026-10-08), and byte-identical for every
//     draft -- first touch or follow-up, every repair round. So one check's
//     write is read by every later check inside the window, including the
//     repair rounds' own checks in the same run.
//   * REPAIR_SYSTEM_PROMPT is 448 tokens. That is BELOW the 512-token minimum,
//     so a breakpoint on it would silently cache nothing and simply bill the
//     write premium -- the docs are explicit that a short prefix fails with no
//     error, and measured here it is 448. It is left uncached deliberately.
//     Padding it to clear the minimum would mean adding text to a prompt to win
//     a few cents, which is the wrong trade. Repairs are rare anyway (only after
//     a claim-check hold, at most 2) and are 25 of the last 206 calls.
const CACHE_CONTROL = { type: 'ephemeral' };

// Sonnet 5.5's documented minimum cacheable prefix (live prompt-caching docs,
// read 2026-10-08). A prefix shorter than this does not cache and does not
// error, so marking one is a pure surcharge -- the build refuses a breakpoint
// on a prompt this short rather than let it go unnoticed.
const MIN_CACHEABLE_TOKENS = 512;

function checkRequest(ctx) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: CHECK_SCHEMA } },
    system: [{ type: 'text', text: CHECK_SYSTEM_PROMPT, cache_control: CACHE_CONTROL }],
    messages: [{ role: 'user', content: checkPrompt(ctx) }],
  };
}

// Did the checker read the whole email? Every sentence it quoted must be in the
// email, and once they are all taken out, nothing may be left. A statement it
// skipped is a statement nobody judged -- the one way a check passes a draft it
// never read.
//
// The prompt shows the subject as "Subject: ...", and the checker copies the
// label with it (measured on the first dry run: "Subject: Your Minimally
// Invasive trial and sponsor inquiries"). The label is not in the email, so it
// is dropped from a quote before matching -- only when the quote leads with it.
function coverage(text, statements) {
  const full = ' ' + apWords(text) + ' ';
  let rest = full;
  const seen = {};
  const foreign = [];
  (statements || []).forEach(function (s) {
    const w = apWords(s && s.sentence).replace(/^subject /, '');
    if (!w || seen[w]) return;
    seen[w] = true;
    const needle = ' ' + w + ' ';
    const at = rest.indexOf(needle);
    if (at !== -1) {
      rest = rest.slice(0, at) + ' ' + rest.slice(at + needle.length);
    } else if (full.indexOf(needle) === -1) {
      foreign.push(apStr(s.sentence));
    }
  });
  const left = rest.trim() ? rest.trim().split(' ') : [];
  return { foreign: foreign, left: left };
}

function sourceCodes(source) {
  return apStr(source).replace(/[\[\]]/g, ' ').split(/[\s,;]+/).map(apStr).filter(Boolean);
}

// The model's answer -> pass, or hold with every reason. The model judges each
// statement; this decides. It never reads a summary verdict from the model --
// there is none to read -- and a claim the model calls "supported" must name a
// confirmed code that exists.
function judgeCheck(resp, ctx) {
  const rec = {
    result: 'hold',
    model: resp && resp.model ? resp.model : null,
    checked_at: new Date().toISOString(),
    usage: resp && resp.usage ? resp.usage : null,
    statements: [],
    reasons: [],
  };
  function fail(reason) {
    rec.reasons = [reason];
    return rec;
  }
  if (!resp || typeof resp !== 'object') return fail('claim-check-failed: no response');
  if (resp.error) {
    const e = resp.error;
    return fail('claim-check-failed: ' + excerpt(typeof e === 'string' ? e : JSON.stringify(e), 200));
  }
  if (resp.stop_reason !== 'end_turn') {
    const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
    return fail('claim-check-failed: stop_reason ' + JSON.stringify(resp.stop_reason) + why);
  }
  const text = (Array.isArray(resp.content) ? resp.content : [])
    .filter(function (b) { return b && b.type === 'text'; })
    .map(function (b) { return b.text; })
    .join('');
  let parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    parsed = null;
  }
  const list = parsed && Array.isArray(parsed.statements) ? parsed.statements : null;
  const wellFormed = list && list.every(function (s) {
    return s && typeof s === 'object' && typeof s.sentence === 'string' && typeof s.statement === 'string' &&
      typeof s.source === 'string' && typeof s.why === 'string' &&
      KINDS.indexOf(s.kind) !== -1 && VERDICTS.indexOf(s.verdict) !== -1;
  });
  if (!wellFormed) return fail('claim-check-failed: the answer was not the check schema: ' + excerpt(text, 120));
  rec.statements = list;

  const reasons = [];
  const cov = coverage(checkText(ctx.check), list);
  if (cov.foreign.length) {
    reasons.push('claim-check-incomplete: quoted text that is not in the email ("' + excerpt(cov.foreign[0], 60) + '")');
  }
  if (cov.left.length) {
    reasons.push('claim-check-incomplete: ' + cov.left.length + ' word' + (cov.left.length === 1 ? '' : 's') +
      ' never reviewed ("' + excerpt(cov.left.join(' '), 60) + '")');
  }
  if (ctx.kind === 'first-touch' && !list.some(function (s) { return s.kind === 'claim'; })) {
    reasons.push('claim-check-incomplete: no product claim found in a first email');
  }

  const ok = confirmedCodes(ctx);
  const problems = [];
  list.forEach(function (s) {
    const what = '"' + excerpt(s.statement || s.sentence) + '"';
    const src = apStr(s.source) ? ' (' + apStr(s.source) + ')' : '';
    if (s.kind === 'claim') {
      const codes = sourceCodes(s.source);
      if (s.verdict !== 'supported') {
        problems.push(s.verdict + ' ' + what + src);
      } else if (!codes.length || codes.some(function (c) { return ok.indexOf(c) === -1; })) {
        problems.push('no confirmed claim behind ' + what + src);
      }
    } else if (s.kind === 'prospect') {
      if (s.verdict !== 'supported') problems.push(s.verdict + ' fact ' + what + src);
    } else if (s.verdict !== 'none') {
      problems.push(s.verdict + ' ' + what + src);
    }
  });
  if (problems.length) reasons.push('claim-check: ' + problems.join('; '));

  rec.reasons = reasons;
  rec.result = reasons.length ? 'hold' : 'pass';
  return rec;
}

// ---------------------------------------------------------------------------
// The repair loop
// ---------------------------------------------------------------------------

// The workflows unroll exactly this many repair rounds; both builds refuse a
// different count.
const MAX_REPAIRS = 2;

// What a repair may fix: a statement the checker judged to say more than its
// source. A check that failed as a process (an HTTP error, a refusal, quotes
// that do not cover the email, a "supported" claim citing no confirmed code) is
// not a sentence the composer can rewrite, so it is held as it is.
const REPAIRABLE = ['widened', 'unsupported', 'joined'];

const REPAIR_SCHEMA = {
  type: 'object',
  properties: {
    rewrites: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          original: { type: 'string' },
          replacement: { type: 'string' },
        },
        required: ['original', 'replacement'],
        additionalProperties: false,
      },
    },
  },
  required: ['rewrites'],
  additionalProperties: false,
};

const REPAIR_SYSTEM_PROMPT = [
  'You repair one outbound sales email that an automatic claim check held. A small company sells a',
  'website assistant to contract research organisations (CROs). The check found sentences that say',
  'more than their sources support. Rewrite ONLY those sentences, so that each says no more than its',
  'source. Every other sentence stays exactly as it is -- you are not shown it to change it.',
  '',
  'You are given APPROVED CLAIMS (the only things the email may say about what we built, what it does,',
  'the problem it addresses, who uses it, and the offer), the PROSPECT RECORD (the only facts about the',
  'recipient), the email, and each flagged sentence with the checker\'s exact reason.',
  '',
  'For each flagged sentence:',
  '- Remove what the checker says goes beyond the source. Say what the approved claim says, in its own',
  '  words, rephrased only for grammar and to fit the sentence.',
  '- Add nothing: no new claim, fact, number, outcome, consequence or name. Shorter is better than',
  '  wider.',
  '- If nothing in the sentence can stay without the widening, make it the approved claim it rests on,',
  '  or return an empty replacement to delete the sentence.',
  '- Keep "(we call it Nova)" if the sentence has it. No greeting, no links.',
  '',
  'Return JSON: rewrites, one per flagged sentence -- "original" (the flagged sentence exactly as it is',
  'given to you) and "replacement".',
].join('\n');

// The flagged sentences, each with every reason the checker gave for it.
function flaggedSentences(statements) {
  const out = [];
  const byKey = {};
  (statements || []).forEach(function (s) {
    if (!s || REPAIRABLE.indexOf(s.verdict) === -1) return;
    const key = apWords(s.sentence).replace(/^subject /, '');
    if (!key) return;
    if (!byKey[key]) {
      byKey[key] = { sentence: apStr(s.sentence).replace(/^subject:\s*/i, ''), reasons: [] };
      out.push(byKey[key]);
    }
    byKey[key].reasons.push({ statement: apStr(s.statement), kind: s.kind, verdict: s.verdict,
      source: apStr(s.source), why: apStr(s.why) });
  });
  return out;
}

function repairPrompt(ctx, flagged) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = ['APPROVED CLAIMS:'].concat(claims.map(function (c) {
    return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body);
  }), ['', 'PROSPECT RECORD:', apStr(ctx.record) || '(nothing is known about them)']);
  if (ctx.kind === 'follow-up' && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only:', '---', apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL:');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '', 'FLAGGED SENTENCES -- rewrite these, and only these:');
  flagged.forEach(function (f, i) {
    out.push(String(i + 1) + '. ' + f.sentence);
    f.reasons.forEach(function (r) {
      out.push('   checker: ' + r.verdict + ' -- "' + r.statement + '"' + (r.source ? ' (compared with ' + r.source + ')' : '') +
        ': ' + r.why);
    });
  });
  return out.join('\n');
}

// No cache_control here on purpose -- REPAIR_SYSTEM_PROMPT is 448 tokens, under
// the 512-token minimum (see the comment above checkRequest).
function repairRequest(ctx, flagged) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: REPAIR_SCHEMA } },
    system: REPAIR_SYSTEM_PROMPT,
    messages: [{ role: 'user', content: repairPrompt(ctx, flagged) }],
  };
}

// Where a quoted sentence sits in a field of the composition: compared word by
// word, folded the same way the coverage check folds, so curly quotes, case and
// accents do not stop a match. The span runs to the end of its trailing
// punctuation.
function tokenSpans(text) {
  const re = /[\p{L}\p{N}]+/gu;
  const out = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    out.push({ w: apWords(m[0]), s: m.index, e: m.index + m[0].length });
  }
  return out.filter(function (t) { return t.w; });
}

function locate(text, quote) {
  const q = apWords(quote).replace(/^subject /, '').split(' ').filter(Boolean);
  if (!q.length) return null;
  const t = tokenSpans(text);
  for (let i = 0; i + q.length <= t.length; i++) {
    let ok = true;
    for (let j = 0; j < q.length; j++) {
      if (t[i + j].w !== q[j]) { ok = false; break; }
    }
    if (ok) {
      let end = t[i + q.length - 1].e;
      while (end < text.length && !/\s/.test(text[end])) end++;
      return { s: t[i].s, e: end };
    }
  }
  return null;
}

// The model's rewrites, applied BY CODE to the fields the email's generated
// text came from. A rewrite whose original is not a flagged sentence is
// ignored, so a repair can change nothing the checker did not flag.
function applyRewrites(composition, fields, flagged, rewrites) {
  const out = JSON.parse(JSON.stringify(composition || {}));
  const keys = {};
  flagged.forEach(function (f) { keys[apWords(f.sentence)] = f; });
  const applied = [];
  const ignored = [];
  (rewrites || []).forEach(function (r) {
    const original = apStr(r && r.original).replace(/^subject:\s*/i, '');
    const replacement = apStr(r && r.replacement);
    const f = keys[apWords(original)];
    if (!f) {
      ignored.push({ original: original, why: 'not a flagged sentence' });
      return;
    }
    for (let i = 0; i < (fields || []).length; i++) {
      const field = fields[i];
      if (typeof out[field] !== 'string') continue;
      const at = locate(out[field], f.sentence);
      if (!at) continue;
      const before = out[field].slice(0, at.s);
      const after = out[field].slice(at.e);
      if (replacement) {
        out[field] = before + replacement + after;
      } else {
        // An empty replacement deletes the sentence, and the space beside it.
        const b = before.replace(/[ \t]+$/, '');
        const a = after.replace(/^[ \t]+/, '');
        out[field] = b + (b && a && !/\n$/.test(b) && !/^\n/.test(a) ? ' ' : '') + a;
      }
      applied.push({ field: field, original: f.sentence, replacement: replacement });
      delete keys[apWords(original)];
      return;
    }
    ignored.push({ original: original, why: 'not found in the email' });
  });
  const changed = applied.some(function (a) { return apWords(a.original) !== apWords(a.replacement); });
  return { composition: out, applied: applied, ignored: ignored, changed: changed };
}

// Every attempt's reasons, for hold_reason. One attempt reads as it always
// did; after repairs each attempt is labelled.
function attemptLabel(n) {
  return n === 1 ? 'first draft' : 'after repair ' + (n - 1);
}

function historyText(history) {
  const list = (history || []).filter(function (h) { return h && Array.isArray(h.reasons); });
  if (list.length === 1 && !list[0].repair_failed) return list[0].reasons.join('; ');
  return list.map(function (h) {
    return attemptLabel(h.attempt) + ': ' + h.reasons.join('; ') + (h.repair_failed ? '; repair ' + h.attempt + ' failed: ' + h.repair_failed : '');
  }).join(' | ');
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const item = $input.item.json;
const ctx = item.approval || null;
// A copy: n8n hands this node the upstream item, and Apply Claim Check reads
// this node's output, not the input.
const payload = JSON.parse(JSON.stringify(item.payload || {}));
const list = draftsOf(payload);

// After a repair: the attempts so far belong to the draft the repair was for.
// If this gate now holds it (a rewrite that broke a rule), every earlier
// attempt's reasons stay on it.
const repair = item.repair && typeof item.repair === 'object' ? item.repair : null;
const prior = repair && Array.isArray(repair.history) ? repair.history : [];

const candidates = [];
list.forEach(function (d, i) {
  const reasons = gateReasons(d, ctx);
  d.status = 'pending';
  d.approved_by = null;
  d.claim_check = null;
  d.hold_reason = reasons.length ? reasons.join('; ') : null;
  if (reasons.length && prior.length && repair.target === i) {
    const history = prior.concat([{ attempt: prior.length + 1, result: 'hold', reasons: reasons, statements: [] }]);
    d.hold_reason = historyText(history);
    d.claim_check = { result: 'hold', reasons: reasons, repairs: prior.length, attempts: history,
      compose_usage: repair.compose_usage || null };
  }
  if (!reasons.length) candidates.push(i);
});

// One email draft per item can reach the check (Workflow 4 writes one email and
// one DM per lead; a follow-up is one email). More would mean a payload this
// node was not written for: hold them all rather than guess.
if (candidates.length > 1) {
  candidates.forEach(function (i) { list[i].hold_reason = 'internal: more than one email draft in one item'; });
  candidates.length = 0;
}

return {
  json: Object.assign({}, item, {
    payload: payload,
    needs_check: candidates.length === 1,
    check_target: candidates.length === 1 ? candidates[0] : null,
    check_request: candidates.length === 1 ? checkRequest(ctx) : null,
  }),
};

// ===========================================================================
// Approval Gate -- n8n Code node (Run Once for Each Item).
//
// Auto-approval of email drafts (migration 014), shared by Workflow 4
// (Drafting) and Workflow 6 (Follow-Ups): both builds embed this file, and
// code_approval_apply.js after everything above this file's "Node body" marker,
// so the two workflows judge a draft with the same functions.
//
// An email draft -- first touch or follow-up -- is approved by the workflow
// that wrote it only if ALL of these hold:
//
//   1. settings.auto_approve_email is on          (read at runtime, migration 014)
//   2. it carries no rule tag                     (nothing after '+' in variant)
//   3. it is not a low-context note, nor a no-send-clock note
//   3b. its lead's country has a Send business-hours clock (Section 12)
//   4. every claim code it records is confirmed   (claims_library.confirmed)
//   5. a second Sonnet 5.5 call compares each product claim with the confirmed
//      claims and each prospect fact with the enrichment record, and every one
//      is supported. A widened claim is a failure.
//
// 1-4 are deterministic and decided HERE, before any money is spent: a draft
// that fails one is held, and the model is not called. 5 is the Claude Claim
// Check node; Apply Claim Check (code_approval_apply.js) reads its answer.
// A LinkedIn draft is never auto-approved (Section 6) and never checked.
//
// A held draft is written 'pending' with hold_reason saying why. The database
// re-checks 1-4 itself (migration 014's drafts_approval_rules) and turns an
// auto-approval that breaks one into a hold, so a bug here can make the
// workflow approve less, never more.
//
// THE REPAIR LOOP (2026-10-03). When 5 holds an email for a widened or
// unsupported statement, the drafting model is sent the email and the
// checker's exact reasons and rewrites only the flagged sentences
// (code_approval_apply.js builds that request; code_approval_repair.js
// applies the rewrites -- by code, so nothing else in the email can change).
// The repaired composition then runs through a second copy of the Assemble
// node (every rule again, the same code), this gate, and the claim check
// again. At most MAX_REPAIRS repairs; the workflows unroll exactly that many
// rounds. Nothing about rules 1-5 is relaxed: a repair is one more chance to
// pass the same checks. A draft is HELD for a claim-check failure only after
// the repairs, and hold_reason then lists every attempt's reasons.
//
// The item this node reads carries `payload` (the drafts Write will insert --
// `payload.drafts` in Workflow 4, `payload.draft` in Follow-Ups) and
// `approval`, the context its Assemble node built:
//
//   approval.kind          'first-touch' | 'follow-up'
//   approval.auto_approve  settings.auto_approve_email, as the batch query read it
//   approval.record        the prospect record: the facts the draft may state
//   approval.claims        [{code, slot, body, confirmed}] -- the lines it may use
//   approval.first_email   the first email as sent (follow-ups only), context
//   approval.check         {subject, text}: the generated text the email carries
//   approval.repair_fields the composition fields that text came from
//
// plus `composition` (the model's parsed answer, which a repair edits) and,
// after a repair, `repair` (the attempts so far, for the record).
//
// A low-context item (Workflow 4's other branch) has no `approval`; its drafts
// are held for what they are.
// ===========================================================================

// Section 3: the claim check is a second call to the drafting model, with the
// drafting node's request parameters -- no temperature/top_p (a 400 on this
// model), adaptive thinking by default, effort set explicitly, JSON through
// output_config.format with a strict schema. Both builds assert these against
// the Master Ref.
const CHECK_MODEL = 'claude-sonnet-5-5';
const CHECK_EFFORT = 'high';
const CHECK_MAX_TOKENS = 16000;

// Section 12's business-hours clocks, as a list of country names, substituted
// at build time from the doc's own table by whichever generator embeds this
// file -- the same table code_decide.js's COUNTRY_CLOCKS is checked against.
//
// Rule 3b. Send refuses an email to a country with no clock for ever
// (`unknown-country`), so approving one would put a draft in the digest's
// auto-approved list that can never go out, and pay for a claim check to get
// there. Assess Grounding already stops such a lead before the drafting call;
// this is the gate's own copy of that rule, because a follow-up, a redraft
// under an older build, or a country removed from the table later would all
// reach here without passing through that branch.
const SEND_CLOCK_COUNTRIES = ["Albania", "Algeria", "Angola", "Argentina", "Armenia", "Australia", "Austria", "Azerbaijan", "Bahamas", "Bahrain", "Bangladesh", "Belgium", "Benin", "Bosnia and Herzegovina", "Brazil", "Bulgaria", "Burkina Faso", "Burundi", "Cambodia", "Cameroon", "Canada", "Chile", "China", "Colombia", "Congo", "Costa Rica", "Cote d'Ivoire", "Croatia", "Cyprus", "Czech Republic", "DR Congo", "Denmark", "Djibouti", "Dominican Republic", "Ecuador", "Egypt", "El Salvador", "Equatorial Guinea", "Estonia", "Ethiopia", "Finland", "France", "Gabon", "Gambia", "Georgia", "Germany", "Ghana", "Greece", "Guatemala", "Guinea", "Hong Kong", "Hungary", "India", "Indonesia", "Ireland", "Israel", "Italy", "Jamaica", "Japan", "Jordan", "Kazakhstan", "Kenya", "Kosovo", "Kuwait", "Kyrgyzstan", "Latvia", "Lebanon", "Liberia", "Lithuania", "Luxembourg", "Macedonia", "Madagascar", "Malawi", "Malaysia", "Mali", "Malta", "Mauritania", "Mauritius", "Mexico", "Moldova", "Mongolia", "Montenegro", "Morocco", "Mozambique", "Nepal", "Netherlands", "New Zealand", "Nigeria", "Norway", "Oman", "Pakistan", "Panama", "Papua New Guinea", "Paraguay", "Peru", "Philippines", "Poland", "Portugal", "Qatar", "Romania", "Rwanda", "Saint Lucia", "Saudi Arabia", "Senegal", "Serbia", "Singapore", "Slovakia", "Slovenia", "South Africa", "South Korea", "Spain", "Sri Lanka", "Suriname", "Sweden", "Switzerland", "Taiwan", "Tanzania", "Thailand", "Togo", "Trinidad and Tobago", "Tunisia", "Turkey", "Turkmenistan", "UAE", "USA", "Uganda", "Ukraine", "United Kingdom", "Uruguay", "Uzbekistan", "Vietnam", "Zambia", "Zimbabwe"];

// One entry per statement, in the email's order. Every object closes with
// additionalProperties:false, which structured outputs requires.
const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    statements: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          sentence: { type: 'string' },
          statement: { type: 'string' },
          kind: { type: 'string', enum: ['claim', 'prospect', 'none'] },
          source: { type: 'string' },
          why: { type: 'string' },
          verdict: { type: 'string', enum: ['supported', 'widened', 'unsupported', 'joined', 'none'] },
        },
        required: ['sentence', 'statement', 'kind', 'source', 'why', 'verdict'],
        additionalProperties: false,
      },
    },
  },
  required: ['statements'],
  additionalProperties: false,
};

// The worked example of a widening is deliberately NOT draft 99's sentence
// ("..., so you know exactly what came in."): that one is the held-out case the
// dry run proves the check catches, and a check shown its own test case proves
// nothing.
const CHECK_SYSTEM_PROMPT = [
  'You check one outbound sales email before it is sent with no human review. A small company',
  'sells a website assistant to contract research organisations (CROs). Your only job is to find',
  'any statement in the email that says more than its sources support.',
  '',
  'You are given:',
  '- APPROVED CLAIMS: the only things the email may say about what we built, what it does, the',
  '  problem it addresses, who uses it, and the offer. Each has a code. The email may rephrase a',
  '  claim; it may never widen one.',
  '- PROSPECT RECORD: the only facts known about the recipient. A fact may say what it does NOT',
  '  establish; that limit is part of the fact.',
  '- Sometimes THE FIRST EMAIL we already sent them, as context. It is not evidence.',
  '- THE EMAIL TO CHECK. Its greeting, opt-out line and signature are fixed text and are not shown.',
  '',
  'Work through the email one sentence at a time, in order. The subject line, when given, counts',
  'as a sentence. Copy each sentence into "sentence" exactly as it appears. A sentence that makes',
  'several statements gets one entry per statement, each with the same "sentence" and its own',
  '"statement" (the words of the sentence that make that statement).',
  '',
  'Classify each statement:',
  '- "claim": anything about what we built, what it does or will do for them, the problem it',
  '  addresses, who uses it, or the offer (the demo).',
  '- "prospect": anything about the recipient -- their company, people, trials, work or website.',
  '- "none": a question that only asks, a reference back to our earlier email that adds nothing',
  '  new, or wording that asserts nothing.',
  'Words an approved claim itself uses about "you" -- your website, your team, your working',
  'hours -- belong to that claim. Judge them as part of the claim, not as prospect facts.',
  'The product\'s name in brackets, "(we call it Nova)", only names what the sentence describes:',
  'it is "none", not a claim. Judge the rest of that sentence as usual.',
  '',
  'Judge each statement:',
  '- claim: "supported" when an approved claim says the same thing or more -- rephrasing,',
  '  shortening and reordering are fine. "widened" when it rests on an approved claim but says',
  '  more: a broader scope, a stronger degree, a certainty or completeness the claim does not',
  '  state, or an added outcome, consequence or capability. "unsupported" when no approved claim',
  '  makes it.',
  '- prospect: "supported" when the record states it. "joined" when it links facts the record',
  '  keeps separate (a trial "in" their city, an area "of" a trial). "unsupported" when the record',
  '  does not state it.',
  '- none: "none".',
  '',
  'An example of widened, for a different claim. Approved: "It sends your capabilities deck the',
  'moment a sponsor asks for it." Email: "It sends your capabilities deck the moment a sponsor',
  'asks, so no request ever goes unanswered." The added clause claims an outcome -- every',
  'request answered -- that the approved claim does not make.',
  '',
  'When you are unsure whether a statement says more than its source, judge it widened or',
  'unsupported: a held email costs a person a minute, and a widened claim sent costs trust.',
  'Do not judge tone, length or style -- only whether each statement is supported.',
  '',
  'For every claim and prospect statement, "source" is the code of the approved claim, or the',
  'number of the record fact, you compared it with ("" when there is none). "why" is one short',
  'sentence.',
].join('\n');

const KINDS = ['claim', 'prospect', 'none'];
const VERDICTS = ['supported', 'widened', 'unsupported', 'joined', 'none'];

function apStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function apFold(v) {
  return apStr(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// The words of a text, for comparing what the checker quoted with what the
// email says: case, accents, punctuation and typographic quotes all fold away.
function apWords(v) {
  return apFold(v).replace(/[^a-z0-9]+/g, ' ').trim();
}

function excerpt(v, n) {
  const t = apStr(v).replace(/\s+/g, ' ');
  const max = n || 90;
  return t.length > max ? t.slice(0, max - 1) + '…' : t;
}

// 'unnamed/D2.ANG-HOURS.BEN-SEE.PR-BOTH.A1+long,claim-repeat'
//   -> codes ['D2','ANG-HOURS','BEN-SEE','PR-BOTH','A1'], tags ['long','claim-repeat']
function variantCodes(variant) {
  const v = apStr(variant);
  const slash = v.indexOf('/');
  return slash === -1 ? [] : v.slice(slash + 1).split('+')[0].split('.').map(apStr).filter(Boolean);
}

function variantTags(variant) {
  const v = apStr(variant);
  const plus = v.indexOf('+');
  return plus === -1 ? [] : v.slice(plus + 1).split(/[,+]/).map(apStr).filter(Boolean);
}

function isLowContext(variant) {
  return /^low-context(\/|$)/.test(apStr(variant));
}

// The other no-model branch (2026-10-07): a lead whose country has no Send
// business-hours clock. Its own prefix, so a reviewer is not told "low context"
// about a lead whose facts were fine.
function isNoSendClock(variant) {
  return /^no-send-clock(\/|$)/.test(apStr(variant));
}

// Section 12's clock table, case-insensitively -- the same way code_decide.js
// looks it up, so the gate and Send can never disagree about one lead.
const SEND_CLOCK_KEYS = SEND_CLOCK_COUNTRIES.map(function (c) { return String(c).toLowerCase(); });

function hasSendClock(country) {
  return SEND_CLOCK_KEYS.indexOf(apStr(country).toLowerCase()) !== -1;
}

// The drafts an item carries, whichever workflow built it.
function draftsOf(payload) {
  if (!payload || typeof payload !== 'object') return [];
  if (Array.isArray(payload.drafts)) return payload.drafts;
  return payload.draft && typeof payload.draft === 'object' ? [payload.draft] : [];
}

function confirmedCodes(ctx) {
  return ((ctx && ctx.claims) || []).filter(function (c) { return c && c.confirmed === true; })
    .map(function (c) { return apStr(c.code); });
}

// Rules 1-4 and the channel rule. Every reason that applies, in this order, so
// the digest and the reviewer see all of them -- not just the first.
function gateReasons(draft, ctx) {
  const reasons = [];
  const variant = apStr(draft && draft.variant);
  if (!draft || draft.channel !== 'email') {
    reasons.push('linkedin: always reviewed and sent by hand');
    return reasons;
  }
  if (isLowContext(variant)) {
    reasons.push('low-context: a note to a person, not an email to send');
    return reasons;
  }
  if (isNoSendClock(variant)) {
    reasons.push('no-send-clock: a note to a person, not an email to send');
    return reasons;
  }
  if (!ctx || typeof ctx !== 'object') {
    reasons.push('no-context: the draft arrived without its approval context');
    return reasons;
  }
  const country = apStr(ctx.country);
  if (!hasSendClock(country)) {
    // Held, not repaired and never checked: no rewrite can give a country a
    // business-hours clock, and Send would refuse the email anyway.
    reasons.push('no-send-clock: ' + (country || '(no country)') +
      ' has no business-hours clock, so this email can never be sent (Section 12)');
    return reasons;
  }
  if (ctx.auto_approve !== true) reasons.push('auto-approve-off: settings.auto_approve_email is false');
  const tags = variantTags(variant);
  if (tags.length) reasons.push('rule-tags: ' + tags.join(', '));
  const codes = variantCodes(variant);
  if (!codes.length) {
    reasons.push('no-claims: the draft records no claim codes');
  } else {
    const ok = confirmedCodes(ctx);
    const bad = codes.filter(function (c) { return ok.indexOf(c) === -1; });
    if (bad.length) reasons.push('unconfirmed-claim: ' + bad.join(', '));
  }
  if (!apStr(ctx.check && ctx.check.text)) reasons.push('no-context: no generated text to check');
  return reasons;
}

function checkText(check) {
  const subject = apStr(check && check.subject);
  return (subject ? subject + '\n' : '') + apStr(check && check.text);
}

function checkPrompt(ctx) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const followUp = ctx.kind === 'follow-up';
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = [
    'APPROVED CLAIMS:',
  ].concat(claims.map(function (c) { return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body); }), [
    '',
    'PROSPECT RECORD:',
    apStr(ctx.record) || '(nothing is known about them)',
  ]);
  if (followUp && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only, not evidence:', '---',
      apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL TO CHECK (' + (followUp ? 'a follow-up to the first email' : 'a first email') + '):');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '',
    'Check every sentence' + (subject ? ', the subject line included' : '') + ', in order.');
  return out.join('\n');
}

// PROMPT CACHING -- on since 2026-10-08 for the claim check, off for the repair.
// The reasoning and the measurements are in code_assess.js's comment; what is
// specific to these two call sites:
//
//   * CHECK_SYSTEM_PROMPT is 1,080 tokens, over Sonnet 5.5's 512-token minimum
//     cacheable prefix (live docs, 2026-10-08), and byte-identical for every
//     draft -- first touch or follow-up, every repair round. So one check's
//     write is read by every later check inside the window, including the
//     repair rounds' own checks in the same run.
//   * REPAIR_SYSTEM_PROMPT is 448 tokens. That is BELOW the 512-token minimum,
//     so a breakpoint on it would silently cache nothing and simply bill the
//     write premium -- the docs are explicit that a short prefix fails with no
//     error, and measured here it is 448. It is left uncached deliberately.
//     Padding it to clear the minimum would mean adding text to a prompt to win
//     a few cents, which is the wrong trade. Repairs are rare anyway (only after
//     a claim-check hold, at most 2) and are 25 of the last 206 calls.
const CACHE_CONTROL = { type: 'ephemeral' };

// Sonnet 5.5's documented minimum cacheable prefix (live prompt-caching docs,
// read 2026-10-08). A prefix shorter than this does not cache and does not
// error, so marking one is a pure surcharge -- the build refuses a breakpoint
// on a prompt this short rather than let it go unnoticed.
const MIN_CACHEABLE_TOKENS = 512;

function checkRequest(ctx) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: CHECK_SCHEMA } },
    system: [{ type: 'text', text: CHECK_SYSTEM_PROMPT, cache_control: CACHE_CONTROL }],
    messages: [{ role: 'user', content: checkPrompt(ctx) }],
  };
}

// Did the checker read the whole email? Every sentence it quoted must be in the
// email, and once they are all taken out, nothing may be left. A statement it
// skipped is a statement nobody judged -- the one way a check passes a draft it
// never read.
//
// The prompt shows the subject as "Subject: ...", and the checker copies the
// label with it (measured on the first dry run: "Subject: Your Minimally
// Invasive trial and sponsor inquiries"). The label is not in the email, so it
// is dropped from a quote before matching -- only when the quote leads with it.
function coverage(text, statements) {
  const full = ' ' + apWords(text) + ' ';
  let rest = full;
  const seen = {};
  const foreign = [];
  (statements || []).forEach(function (s) {
    const w = apWords(s && s.sentence).replace(/^subject /, '');
    if (!w || seen[w]) return;
    seen[w] = true;
    const needle = ' ' + w + ' ';
    const at = rest.indexOf(needle);
    if (at !== -1) {
      rest = rest.slice(0, at) + ' ' + rest.slice(at + needle.length);
    } else if (full.indexOf(needle) === -1) {
      foreign.push(apStr(s.sentence));
    }
  });
  const left = rest.trim() ? rest.trim().split(' ') : [];
  return { foreign: foreign, left: left };
}

function sourceCodes(source) {
  return apStr(source).replace(/[\[\]]/g, ' ').split(/[\s,;]+/).map(apStr).filter(Boolean);
}

// The model's answer -> pass, or hold with every reason. The model judges each
// statement; this decides. It never reads a summary verdict from the model --
// there is none to read -- and a claim the model calls "supported" must name a
// confirmed code that exists.
function judgeCheck(resp, ctx) {
  const rec = {
    result: 'hold',
    model: resp && resp.model ? resp.model : null,
    checked_at: new Date().toISOString(),
    usage: resp && resp.usage ? resp.usage : null,
    statements: [],
    reasons: [],
  };
  function fail(reason) {
    rec.reasons = [reason];
    return rec;
  }
  if (!resp || typeof resp !== 'object') return fail('claim-check-failed: no response');
  if (resp.error) {
    const e = resp.error;
    return fail('claim-check-failed: ' + excerpt(typeof e === 'string' ? e : JSON.stringify(e), 200));
  }
  if (resp.stop_reason !== 'end_turn') {
    const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
    return fail('claim-check-failed: stop_reason ' + JSON.stringify(resp.stop_reason) + why);
  }
  const text = (Array.isArray(resp.content) ? resp.content : [])
    .filter(function (b) { return b && b.type === 'text'; })
    .map(function (b) { return b.text; })
    .join('');
  let parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    parsed = null;
  }
  const list = parsed && Array.isArray(parsed.statements) ? parsed.statements : null;
  const wellFormed = list && list.every(function (s) {
    return s && typeof s === 'object' && typeof s.sentence === 'string' && typeof s.statement === 'string' &&
      typeof s.source === 'string' && typeof s.why === 'string' &&
      KINDS.indexOf(s.kind) !== -1 && VERDICTS.indexOf(s.verdict) !== -1;
  });
  if (!wellFormed) return fail('claim-check-failed: the answer was not the check schema: ' + excerpt(text, 120));
  rec.statements = list;

  const reasons = [];
  const cov = coverage(checkText(ctx.check), list);
  if (cov.foreign.length) {
    reasons.push('claim-check-incomplete: quoted text that is not in the email ("' + excerpt(cov.foreign[0], 60) + '")');
  }
  if (cov.left.length) {
    reasons.push('claim-check-incomplete: ' + cov.left.length + ' word' + (cov.left.length === 1 ? '' : 's') +
      ' never reviewed ("' + excerpt(cov.left.join(' '), 60) + '")');
  }
  if (ctx.kind === 'first-touch' && !list.some(function (s) { return s.kind === 'claim'; })) {
    reasons.push('claim-check-incomplete: no product claim found in a first email');
  }

  const ok = confirmedCodes(ctx);
  const problems = [];
  list.forEach(function (s) {
    const what = '"' + excerpt(s.statement || s.sentence) + '"';
    const src = apStr(s.source) ? ' (' + apStr(s.source) + ')' : '';
    if (s.kind === 'claim') {
      const codes = sourceCodes(s.source);
      if (s.verdict !== 'supported') {
        problems.push(s.verdict + ' ' + what + src);
      } else if (!codes.length || codes.some(function (c) { return ok.indexOf(c) === -1; })) {
        problems.push('no confirmed claim behind ' + what + src);
      }
    } else if (s.kind === 'prospect') {
      if (s.verdict !== 'supported') problems.push(s.verdict + ' fact ' + what + src);
    } else if (s.verdict !== 'none') {
      problems.push(s.verdict + ' ' + what + src);
    }
  });
  if (problems.length) reasons.push('claim-check: ' + problems.join('; '));

  rec.reasons = reasons;
  rec.result = reasons.length ? 'hold' : 'pass';
  return rec;
}

// ---------------------------------------------------------------------------
// The repair loop
// ---------------------------------------------------------------------------

// The workflows unroll exactly this many repair rounds; both builds refuse a
// different count.
const MAX_REPAIRS = 2;

// What a repair may fix: a statement the checker judged to say more than its
// source. A check that failed as a process (an HTTP error, a refusal, quotes
// that do not cover the email, a "supported" claim citing no confirmed code) is
// not a sentence the composer can rewrite, so it is held as it is.
const REPAIRABLE = ['widened', 'unsupported', 'joined'];

const REPAIR_SCHEMA = {
  type: 'object',
  properties: {
    rewrites: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          original: { type: 'string' },
          replacement: { type: 'string' },
        },
        required: ['original', 'replacement'],
        additionalProperties: false,
      },
    },
  },
  required: ['rewrites'],
  additionalProperties: false,
};

const REPAIR_SYSTEM_PROMPT = [
  'You repair one outbound sales email that an automatic claim check held. A small company sells a',
  'website assistant to contract research organisations (CROs). The check found sentences that say',
  'more than their sources support. Rewrite ONLY those sentences, so that each says no more than its',
  'source. Every other sentence stays exactly as it is -- you are not shown it to change it.',
  '',
  'You are given APPROVED CLAIMS (the only things the email may say about what we built, what it does,',
  'the problem it addresses, who uses it, and the offer), the PROSPECT RECORD (the only facts about the',
  'recipient), the email, and each flagged sentence with the checker\'s exact reason.',
  '',
  'For each flagged sentence:',
  '- Remove what the checker says goes beyond the source. Say what the approved claim says, in its own',
  '  words, rephrased only for grammar and to fit the sentence.',
  '- Add nothing: no new claim, fact, number, outcome, consequence or name. Shorter is better than',
  '  wider.',
  '- If nothing in the sentence can stay without the widening, make it the approved claim it rests on,',
  '  or return an empty replacement to delete the sentence.',
  '- Keep "(we call it Nova)" if the sentence has it. No greeting, no links.',
  '',
  'Return JSON: rewrites, one per flagged sentence -- "original" (the flagged sentence exactly as it is',
  'given to you) and "replacement".',
].join('\n');

// The flagged sentences, each with every reason the checker gave for it.
function flaggedSentences(statements) {
  const out = [];
  const byKey = {};
  (statements || []).forEach(function (s) {
    if (!s || REPAIRABLE.indexOf(s.verdict) === -1) return;
    const key = apWords(s.sentence).replace(/^subject /, '');
    if (!key) return;
    if (!byKey[key]) {
      byKey[key] = { sentence: apStr(s.sentence).replace(/^subject:\s*/i, ''), reasons: [] };
      out.push(byKey[key]);
    }
    byKey[key].reasons.push({ statement: apStr(s.statement), kind: s.kind, verdict: s.verdict,
      source: apStr(s.source), why: apStr(s.why) });
  });
  return out;
}

function repairPrompt(ctx, flagged) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = ['APPROVED CLAIMS:'].concat(claims.map(function (c) {
    return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body);
  }), ['', 'PROSPECT RECORD:', apStr(ctx.record) || '(nothing is known about them)']);
  if (ctx.kind === 'follow-up' && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only:', '---', apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL:');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '', 'FLAGGED SENTENCES -- rewrite these, and only these:');
  flagged.forEach(function (f, i) {
    out.push(String(i + 1) + '. ' + f.sentence);
    f.reasons.forEach(function (r) {
      out.push('   checker: ' + r.verdict + ' -- "' + r.statement + '"' + (r.source ? ' (compared with ' + r.source + ')' : '') +
        ': ' + r.why);
    });
  });
  return out.join('\n');
}

// No cache_control here on purpose -- REPAIR_SYSTEM_PROMPT is 448 tokens, under
// the 512-token minimum (see the comment above checkRequest).
function repairRequest(ctx, flagged) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: REPAIR_SCHEMA } },
    system: REPAIR_SYSTEM_PROMPT,
    messages: [{ role: 'user', content: repairPrompt(ctx, flagged) }],
  };
}

// Where a quoted sentence sits in a field of the composition: compared word by
// word, folded the same way the coverage check folds, so curly quotes, case and
// accents do not stop a match. The span runs to the end of its trailing
// punctuation.
function tokenSpans(text) {
  const re = /[\p{L}\p{N}]+/gu;
  const out = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    out.push({ w: apWords(m[0]), s: m.index, e: m.index + m[0].length });
  }
  return out.filter(function (t) { return t.w; });
}

function locate(text, quote) {
  const q = apWords(quote).replace(/^subject /, '').split(' ').filter(Boolean);
  if (!q.length) return null;
  const t = tokenSpans(text);
  for (let i = 0; i + q.length <= t.length; i++) {
    let ok = true;
    for (let j = 0; j < q.length; j++) {
      if (t[i + j].w !== q[j]) { ok = false; break; }
    }
    if (ok) {
      let end = t[i + q.length - 1].e;
      while (end < text.length && !/\s/.test(text[end])) end++;
      return { s: t[i].s, e: end };
    }
  }
  return null;
}

// The model's rewrites, applied BY CODE to the fields the email's generated
// text came from. A rewrite whose original is not a flagged sentence is
// ignored, so a repair can change nothing the checker did not flag.
function applyRewrites(composition, fields, flagged, rewrites) {
  const out = JSON.parse(JSON.stringify(composition || {}));
  const keys = {};
  flagged.forEach(function (f) { keys[apWords(f.sentence)] = f; });
  const applied = [];
  const ignored = [];
  (rewrites || []).forEach(function (r) {
    const original = apStr(r && r.original).replace(/^subject:\s*/i, '');
    const replacement = apStr(r && r.replacement);
    const f = keys[apWords(original)];
    if (!f) {
      ignored.push({ original: original, why: 'not a flagged sentence' });
      return;
    }
    for (let i = 0; i < (fields || []).length; i++) {
      const field = fields[i];
      if (typeof out[field] !== 'string') continue;
      const at = locate(out[field], f.sentence);
      if (!at) continue;
      const before = out[field].slice(0, at.s);
      const after = out[field].slice(at.e);
      if (replacement) {
        out[field] = before + replacement + after;
      } else {
        // An empty replacement deletes the sentence, and the space beside it.
        const b = before.replace(/[ \t]+$/, '');
        const a = after.replace(/^[ \t]+/, '');
        out[field] = b + (b && a && !/\n$/.test(b) && !/^\n/.test(a) ? ' ' : '') + a;
      }
      applied.push({ field: field, original: f.sentence, replacement: replacement });
      delete keys[apWords(original)];
      return;
    }
    ignored.push({ original: original, why: 'not found in the email' });
  });
  const changed = applied.some(function (a) { return apWords(a.original) !== apWords(a.replacement); });
  return { composition: out, applied: applied, ignored: ignored, changed: changed };
}

// Every attempt's reasons, for hold_reason. One attempt reads as it always
// did; after repairs each attempt is labelled.
function attemptLabel(n) {
  return n === 1 ? 'first draft' : 'after repair ' + (n - 1);
}

function historyText(history) {
  const list = (history || []).filter(function (h) { return h && Array.isArray(h.reasons); });
  if (list.length === 1 && !list[0].repair_failed) return list[0].reasons.join('; ');
  return list.map(function (h) {
    return attemptLabel(h.attempt) + ': ' + h.reasons.join('; ') + (h.repair_failed ? '; repair ' + h.attempt + ' failed: ' + h.repair_failed : '');
  }).join(' | ');
}

// ---------------------------------------------------------------------------

// ===========================================================================
// Apply Claim Check -- n8n Code node (Run Once for Each Item).
//
// Shipped as code_approval.js above its "Node body" marker (the rules, verbatim)
// followed by this file, in Workflow 4 and in Follow-Ups alike -- once per
// attempt: the first draft, and after each repair. The build bakes in which
// Approval Gate copy this one follows ('Approval Gate', 'Approval Gate R1',
// ...).
//
// Reads that gate's item -- the draft that passed rules 1-4 -- and the Claude
// Claim Check node's answer for it, and decides rule 5: approved by the
// workflow ('approved', approved_by 'auto') only if every statement the model
// found is supported AND the model's quotes account for the whole email. Any
// failed call -- an HTTP error, a refusal, a cut-off, an answer that is not the
// schema -- holds the draft for a human: the draft itself is fine, so it is
// written, pending, with the reason. Nothing falls back to another model; the
// check is Sonnet 5.5's or it is a human's.
//
// The repair loop: when the hold names statements that say more than their
// source (widened, unsupported, joined) and fewer than MAX_REPAIRS repairs
// have been made, the item asks for a repair (needs_repair, repair_request)
// instead of ending here: the drafting model is sent the email and the
// checker's exact reasons, and code_approval_repair.js applies its rewrites.
// Otherwise the hold is final, and hold_reason lists every attempt's reasons.
//
// The verdicts of every attempt, the model and the usage go into the draft's
// claim_check either way, so a held draft shows the reviewer exactly which
// sentence failed each time, and the cost of a draft includes its repairs.
// ===========================================================================

// Node body

const gate = $('Approval Gate R1').item.json;
const resp = $input.item.json;
const payload = JSON.parse(JSON.stringify(gate.payload || {}));
const target = draftsOf(payload)[gate.check_target];

if (!target) {
  throw new Error('Apply Claim Check: the Approval Gate item has no draft at check_target ' +
    JSON.stringify(gate.check_target));
}

const verdict = judgeCheck(resp, gate.approval);
const repairState = gate.repair && typeof gate.repair === 'object' ? gate.repair : null;
const prior = repairState && Array.isArray(repairState.history) ? repairState.history : [];
const attempt = {
  attempt: prior.length + 1,
  result: verdict.result,
  reasons: verdict.reasons,
  statements: verdict.statements,
  check_usage: verdict.usage,
  // The repair that produced this text, if any: its rewrites and its cost.
  repair_usage: repairState ? repairState.last_repair_usage || null : null,
  rewrites: repairState ? repairState.rewrites || [] : [],
};
const history = prior.concat([attempt]);
const composeUsage = repairState ? repairState.compose_usage || null : gate.usage || null;

const flagged = verdict.result === 'hold' ? flaggedSentences(verdict.statements) : [];
const fields = (gate.approval && gate.approval.repair_fields) || [];
const canRepair = flagged.length > 0 && prior.length < MAX_REPAIRS && fields.length > 0 &&
  !!gate.composition && typeof gate.composition === 'object';

target.claim_check = Object.assign({}, verdict, {
  repairs: prior.length,
  attempts: history,
  compose_usage: composeUsage,
});
if (verdict.result === 'pass') {
  target.status = 'approved';
  target.approved_by = 'auto';
  target.hold_reason = null;
} else {
  target.status = 'pending';
  target.approved_by = null;
  target.hold_reason = historyText(history);
}

return {
  json: Object.assign({}, gate, {
    payload: payload,
    check_request: null,
    check_result: verdict.result,
    check_reasons: verdict.reasons,
    check_usage: verdict.usage,
    needs_repair: canRepair,
    repair_request: canRepair ? repairRequest(gate.approval, flagged) : null,
    repair_state: canRepair ? {
      target: gate.check_target,
      history: history,
      flagged: flagged,
      composition: gate.composition,
      compose_usage: composeUsage,
    } : null,
  }),
};

// ===========================================================================
// Approval Gate -- n8n Code node (Run Once for Each Item).
//
// Auto-approval of email drafts (migration 014), shared by Workflow 4
// (Drafting) and Workflow 6 (Follow-Ups): both builds embed this file, and
// code_approval_apply.js after everything above this file's "Node body" marker,
// so the two workflows judge a draft with the same functions.
//
// An email draft -- first touch or follow-up -- is approved by the workflow
// that wrote it only if ALL of these hold:
//
//   1. settings.auto_approve_email is on          (read at runtime, migration 014)
//   2. it carries no rule tag                     (nothing after '+' in variant)
//   3. it is not a low-context note, nor a no-send-clock note
//   3b. its lead's country has a Send business-hours clock (Section 12)
//   4. every claim code it records is confirmed   (claims_library.confirmed)
//   5. a second Sonnet 5.5 call compares each product claim with the confirmed
//      claims and each prospect fact with the enrichment record, and every one
//      is supported. A widened claim is a failure.
//
// 1-4 are deterministic and decided HERE, before any money is spent: a draft
// that fails one is held, and the model is not called. 5 is the Claude Claim
// Check node; Apply Claim Check (code_approval_apply.js) reads its answer.
// A LinkedIn draft is never auto-approved (Section 6) and never checked.
//
// A held draft is written 'pending' with hold_reason saying why. The database
// re-checks 1-4 itself (migration 014's drafts_approval_rules) and turns an
// auto-approval that breaks one into a hold, so a bug here can make the
// workflow approve less, never more.
//
// THE REPAIR LOOP (2026-10-03). When 5 holds an email for a widened or
// unsupported statement, the drafting model is sent the email and the
// checker's exact reasons and rewrites only the flagged sentences
// (code_approval_apply.js builds that request; code_approval_repair.js
// applies the rewrites -- by code, so nothing else in the email can change).
// The repaired composition then runs through a second copy of the Assemble
// node (every rule again, the same code), this gate, and the claim check
// again. At most MAX_REPAIRS repairs; the workflows unroll exactly that many
// rounds. Nothing about rules 1-5 is relaxed: a repair is one more chance to
// pass the same checks. A draft is HELD for a claim-check failure only after
// the repairs, and hold_reason then lists every attempt's reasons.
//
// The item this node reads carries `payload` (the drafts Write will insert --
// `payload.drafts` in Workflow 4, `payload.draft` in Follow-Ups) and
// `approval`, the context its Assemble node built:
//
//   approval.kind          'first-touch' | 'follow-up'
//   approval.auto_approve  settings.auto_approve_email, as the batch query read it
//   approval.record        the prospect record: the facts the draft may state
//   approval.claims        [{code, slot, body, confirmed}] -- the lines it may use
//   approval.first_email   the first email as sent (follow-ups only), context
//   approval.check         {subject, text}: the generated text the email carries
//   approval.repair_fields the composition fields that text came from
//
// plus `composition` (the model's parsed answer, which a repair edits) and,
// after a repair, `repair` (the attempts so far, for the record).
//
// A low-context item (Workflow 4's other branch) has no `approval`; its drafts
// are held for what they are.
// ===========================================================================

// Section 3: the claim check is a second call to the drafting model, with the
// drafting node's request parameters -- no temperature/top_p (a 400 on this
// model), adaptive thinking by default, effort set explicitly, JSON through
// output_config.format with a strict schema. Both builds assert these against
// the Master Ref.
const CHECK_MODEL = 'claude-sonnet-5-5';
const CHECK_EFFORT = 'high';
const CHECK_MAX_TOKENS = 16000;

// Section 12's business-hours clocks, as a list of country names, substituted
// at build time from the doc's own table by whichever generator embeds this
// file -- the same table code_decide.js's COUNTRY_CLOCKS is checked against.
//
// Rule 3b. Send refuses an email to a country with no clock for ever
// (`unknown-country`), so approving one would put a draft in the digest's
// auto-approved list that can never go out, and pay for a claim check to get
// there. Assess Grounding already stops such a lead before the drafting call;
// this is the gate's own copy of that rule, because a follow-up, a redraft
// under an older build, or a country removed from the table later would all
// reach here without passing through that branch.
const SEND_CLOCK_COUNTRIES = ["Albania", "Algeria", "Angola", "Argentina", "Armenia", "Australia", "Austria", "Azerbaijan", "Bahamas", "Bahrain", "Bangladesh", "Belgium", "Benin", "Bosnia and Herzegovina", "Brazil", "Bulgaria", "Burkina Faso", "Burundi", "Cambodia", "Cameroon", "Canada", "Chile", "China", "Colombia", "Congo", "Costa Rica", "Cote d'Ivoire", "Croatia", "Cyprus", "Czech Republic", "DR Congo", "Denmark", "Djibouti", "Dominican Republic", "Ecuador", "Egypt", "El Salvador", "Equatorial Guinea", "Estonia", "Ethiopia", "Finland", "France", "Gabon", "Gambia", "Georgia", "Germany", "Ghana", "Greece", "Guatemala", "Guinea", "Hong Kong", "Hungary", "India", "Indonesia", "Ireland", "Israel", "Italy", "Jamaica", "Japan", "Jordan", "Kazakhstan", "Kenya", "Kosovo", "Kuwait", "Kyrgyzstan", "Latvia", "Lebanon", "Liberia", "Lithuania", "Luxembourg", "Macedonia", "Madagascar", "Malawi", "Malaysia", "Mali", "Malta", "Mauritania", "Mauritius", "Mexico", "Moldova", "Mongolia", "Montenegro", "Morocco", "Mozambique", "Nepal", "Netherlands", "New Zealand", "Nigeria", "Norway", "Oman", "Pakistan", "Panama", "Papua New Guinea", "Paraguay", "Peru", "Philippines", "Poland", "Portugal", "Qatar", "Romania", "Rwanda", "Saint Lucia", "Saudi Arabia", "Senegal", "Serbia", "Singapore", "Slovakia", "Slovenia", "South Africa", "South Korea", "Spain", "Sri Lanka", "Suriname", "Sweden", "Switzerland", "Taiwan", "Tanzania", "Thailand", "Togo", "Trinidad and Tobago", "Tunisia", "Turkey", "Turkmenistan", "UAE", "USA", "Uganda", "Ukraine", "United Kingdom", "Uruguay", "Uzbekistan", "Vietnam", "Zambia", "Zimbabwe"];

// One entry per statement, in the email's order. Every object closes with
// additionalProperties:false, which structured outputs requires.
const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    statements: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          sentence: { type: 'string' },
          statement: { type: 'string' },
          kind: { type: 'string', enum: ['claim', 'prospect', 'none'] },
          source: { type: 'string' },
          why: { type: 'string' },
          verdict: { type: 'string', enum: ['supported', 'widened', 'unsupported', 'joined', 'none'] },
        },
        required: ['sentence', 'statement', 'kind', 'source', 'why', 'verdict'],
        additionalProperties: false,
      },
    },
  },
  required: ['statements'],
  additionalProperties: false,
};

// The worked example of a widening is deliberately NOT draft 99's sentence
// ("..., so you know exactly what came in."): that one is the held-out case the
// dry run proves the check catches, and a check shown its own test case proves
// nothing.
const CHECK_SYSTEM_PROMPT = [
  'You check one outbound sales email before it is sent with no human review. A small company',
  'sells a website assistant to contract research organisations (CROs). Your only job is to find',
  'any statement in the email that says more than its sources support.',
  '',
  'You are given:',
  '- APPROVED CLAIMS: the only things the email may say about what we built, what it does, the',
  '  problem it addresses, who uses it, and the offer. Each has a code. The email may rephrase a',
  '  claim; it may never widen one.',
  '- PROSPECT RECORD: the only facts known about the recipient. A fact may say what it does NOT',
  '  establish; that limit is part of the fact.',
  '- Sometimes THE FIRST EMAIL we already sent them, as context. It is not evidence.',
  '- THE EMAIL TO CHECK. Its greeting, opt-out line and signature are fixed text and are not shown.',
  '',
  'Work through the email one sentence at a time, in order. The subject line, when given, counts',
  'as a sentence. Copy each sentence into "sentence" exactly as it appears. A sentence that makes',
  'several statements gets one entry per statement, each with the same "sentence" and its own',
  '"statement" (the words of the sentence that make that statement).',
  '',
  'Classify each statement:',
  '- "claim": anything about what we built, what it does or will do for them, the problem it',
  '  addresses, who uses it, or the offer (the demo).',
  '- "prospect": anything about the recipient -- their company, people, trials, work or website.',
  '- "none": a question that only asks, a reference back to our earlier email that adds nothing',
  '  new, or wording that asserts nothing.',
  'Words an approved claim itself uses about "you" -- your website, your team, your working',
  'hours -- belong to that claim. Judge them as part of the claim, not as prospect facts.',
  'The product\'s name in brackets, "(we call it Nova)", only names what the sentence describes:',
  'it is "none", not a claim. Judge the rest of that sentence as usual.',
  '',
  'Judge each statement:',
  '- claim: "supported" when an approved claim says the same thing or more -- rephrasing,',
  '  shortening and reordering are fine. "widened" when it rests on an approved claim but says',
  '  more: a broader scope, a stronger degree, a certainty or completeness the claim does not',
  '  state, or an added outcome, consequence or capability. "unsupported" when no approved claim',
  '  makes it.',
  '- prospect: "supported" when the record states it. "joined" when it links facts the record',
  '  keeps separate (a trial "in" their city, an area "of" a trial). "unsupported" when the record',
  '  does not state it.',
  '- none: "none".',
  '',
  'An example of widened, for a different claim. Approved: "It sends your capabilities deck the',
  'moment a sponsor asks for it." Email: "It sends your capabilities deck the moment a sponsor',
  'asks, so no request ever goes unanswered." The added clause claims an outcome -- every',
  'request answered -- that the approved claim does not make.',
  '',
  'When you are unsure whether a statement says more than its source, judge it widened or',
  'unsupported: a held email costs a person a minute, and a widened claim sent costs trust.',
  'Do not judge tone, length or style -- only whether each statement is supported.',
  '',
  'For every claim and prospect statement, "source" is the code of the approved claim, or the',
  'number of the record fact, you compared it with ("" when there is none). "why" is one short',
  'sentence.',
].join('\n');

const KINDS = ['claim', 'prospect', 'none'];
const VERDICTS = ['supported', 'widened', 'unsupported', 'joined', 'none'];

function apStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function apFold(v) {
  return apStr(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// The words of a text, for comparing what the checker quoted with what the
// email says: case, accents, punctuation and typographic quotes all fold away.
function apWords(v) {
  return apFold(v).replace(/[^a-z0-9]+/g, ' ').trim();
}

function excerpt(v, n) {
  const t = apStr(v).replace(/\s+/g, ' ');
  const max = n || 90;
  return t.length > max ? t.slice(0, max - 1) + '…' : t;
}

// 'unnamed/D2.ANG-HOURS.BEN-SEE.PR-BOTH.A1+long,claim-repeat'
//   -> codes ['D2','ANG-HOURS','BEN-SEE','PR-BOTH','A1'], tags ['long','claim-repeat']
function variantCodes(variant) {
  const v = apStr(variant);
  const slash = v.indexOf('/');
  return slash === -1 ? [] : v.slice(slash + 1).split('+')[0].split('.').map(apStr).filter(Boolean);
}

function variantTags(variant) {
  const v = apStr(variant);
  const plus = v.indexOf('+');
  return plus === -1 ? [] : v.slice(plus + 1).split(/[,+]/).map(apStr).filter(Boolean);
}

function isLowContext(variant) {
  return /^low-context(\/|$)/.test(apStr(variant));
}

// The other no-model branch (2026-10-07): a lead whose country has no Send
// business-hours clock. Its own prefix, so a reviewer is not told "low context"
// about a lead whose facts were fine.
function isNoSendClock(variant) {
  return /^no-send-clock(\/|$)/.test(apStr(variant));
}

// Section 12's clock table, case-insensitively -- the same way code_decide.js
// looks it up, so the gate and Send can never disagree about one lead.
const SEND_CLOCK_KEYS = SEND_CLOCK_COUNTRIES.map(function (c) { return String(c).toLowerCase(); });

function hasSendClock(country) {
  return SEND_CLOCK_KEYS.indexOf(apStr(country).toLowerCase()) !== -1;
}

// The drafts an item carries, whichever workflow built it.
function draftsOf(payload) {
  if (!payload || typeof payload !== 'object') return [];
  if (Array.isArray(payload.drafts)) return payload.drafts;
  return payload.draft && typeof payload.draft === 'object' ? [payload.draft] : [];
}

function confirmedCodes(ctx) {
  return ((ctx && ctx.claims) || []).filter(function (c) { return c && c.confirmed === true; })
    .map(function (c) { return apStr(c.code); });
}

// Rules 1-4 and the channel rule. Every reason that applies, in this order, so
// the digest and the reviewer see all of them -- not just the first.
function gateReasons(draft, ctx) {
  const reasons = [];
  const variant = apStr(draft && draft.variant);
  if (!draft || draft.channel !== 'email') {
    reasons.push('linkedin: always reviewed and sent by hand');
    return reasons;
  }
  if (isLowContext(variant)) {
    reasons.push('low-context: a note to a person, not an email to send');
    return reasons;
  }
  if (isNoSendClock(variant)) {
    reasons.push('no-send-clock: a note to a person, not an email to send');
    return reasons;
  }
  if (!ctx || typeof ctx !== 'object') {
    reasons.push('no-context: the draft arrived without its approval context');
    return reasons;
  }
  const country = apStr(ctx.country);
  if (!hasSendClock(country)) {
    // Held, not repaired and never checked: no rewrite can give a country a
    // business-hours clock, and Send would refuse the email anyway.
    reasons.push('no-send-clock: ' + (country || '(no country)') +
      ' has no business-hours clock, so this email can never be sent (Section 12)');
    return reasons;
  }
  if (ctx.auto_approve !== true) reasons.push('auto-approve-off: settings.auto_approve_email is false');
  const tags = variantTags(variant);
  if (tags.length) reasons.push('rule-tags: ' + tags.join(', '));
  const codes = variantCodes(variant);
  if (!codes.length) {
    reasons.push('no-claims: the draft records no claim codes');
  } else {
    const ok = confirmedCodes(ctx);
    const bad = codes.filter(function (c) { return ok.indexOf(c) === -1; });
    if (bad.length) reasons.push('unconfirmed-claim: ' + bad.join(', '));
  }
  if (!apStr(ctx.check && ctx.check.text)) reasons.push('no-context: no generated text to check');
  return reasons;
}

function checkText(check) {
  const subject = apStr(check && check.subject);
  return (subject ? subject + '\n' : '') + apStr(check && check.text);
}

function checkPrompt(ctx) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const followUp = ctx.kind === 'follow-up';
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = [
    'APPROVED CLAIMS:',
  ].concat(claims.map(function (c) { return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body); }), [
    '',
    'PROSPECT RECORD:',
    apStr(ctx.record) || '(nothing is known about them)',
  ]);
  if (followUp && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only, not evidence:', '---',
      apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL TO CHECK (' + (followUp ? 'a follow-up to the first email' : 'a first email') + '):');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '',
    'Check every sentence' + (subject ? ', the subject line included' : '') + ', in order.');
  return out.join('\n');
}

// PROMPT CACHING -- on since 2026-10-08 for the claim check, off for the repair.
// The reasoning and the measurements are in code_assess.js's comment; what is
// specific to these two call sites:
//
//   * CHECK_SYSTEM_PROMPT is 1,080 tokens, over Sonnet 5.5's 512-token minimum
//     cacheable prefix (live docs, 2026-10-08), and byte-identical for every
//     draft -- first touch or follow-up, every repair round. So one check's
//     write is read by every later check inside the window, including the
//     repair rounds' own checks in the same run.
//   * REPAIR_SYSTEM_PROMPT is 448 tokens. That is BELOW the 512-token minimum,
//     so a breakpoint on it would silently cache nothing and simply bill the
//     write premium -- the docs are explicit that a short prefix fails with no
//     error, and measured here it is 448. It is left uncached deliberately.
//     Padding it to clear the minimum would mean adding text to a prompt to win
//     a few cents, which is the wrong trade. Repairs are rare anyway (only after
//     a claim-check hold, at most 2) and are 25 of the last 206 calls.
const CACHE_CONTROL = { type: 'ephemeral' };

// Sonnet 5.5's documented minimum cacheable prefix (live prompt-caching docs,
// read 2026-10-08). A prefix shorter than this does not cache and does not
// error, so marking one is a pure surcharge -- the build refuses a breakpoint
// on a prompt this short rather than let it go unnoticed.
const MIN_CACHEABLE_TOKENS = 512;

function checkRequest(ctx) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: CHECK_SCHEMA } },
    system: [{ type: 'text', text: CHECK_SYSTEM_PROMPT, cache_control: CACHE_CONTROL }],
    messages: [{ role: 'user', content: checkPrompt(ctx) }],
  };
}

// Did the checker read the whole email? Every sentence it quoted must be in the
// email, and once they are all taken out, nothing may be left. A statement it
// skipped is a statement nobody judged -- the one way a check passes a draft it
// never read.
//
// The prompt shows the subject as "Subject: ...", and the checker copies the
// label with it (measured on the first dry run: "Subject: Your Minimally
// Invasive trial and sponsor inquiries"). The label is not in the email, so it
// is dropped from a quote before matching -- only when the quote leads with it.
function coverage(text, statements) {
  const full = ' ' + apWords(text) + ' ';
  let rest = full;
  const seen = {};
  const foreign = [];
  (statements || []).forEach(function (s) {
    const w = apWords(s && s.sentence).replace(/^subject /, '');
    if (!w || seen[w]) return;
    seen[w] = true;
    const needle = ' ' + w + ' ';
    const at = rest.indexOf(needle);
    if (at !== -1) {
      rest = rest.slice(0, at) + ' ' + rest.slice(at + needle.length);
    } else if (full.indexOf(needle) === -1) {
      foreign.push(apStr(s.sentence));
    }
  });
  const left = rest.trim() ? rest.trim().split(' ') : [];
  return { foreign: foreign, left: left };
}

function sourceCodes(source) {
  return apStr(source).replace(/[\[\]]/g, ' ').split(/[\s,;]+/).map(apStr).filter(Boolean);
}

// The model's answer -> pass, or hold with every reason. The model judges each
// statement; this decides. It never reads a summary verdict from the model --
// there is none to read -- and a claim the model calls "supported" must name a
// confirmed code that exists.
function judgeCheck(resp, ctx) {
  const rec = {
    result: 'hold',
    model: resp && resp.model ? resp.model : null,
    checked_at: new Date().toISOString(),
    usage: resp && resp.usage ? resp.usage : null,
    statements: [],
    reasons: [],
  };
  function fail(reason) {
    rec.reasons = [reason];
    return rec;
  }
  if (!resp || typeof resp !== 'object') return fail('claim-check-failed: no response');
  if (resp.error) {
    const e = resp.error;
    return fail('claim-check-failed: ' + excerpt(typeof e === 'string' ? e : JSON.stringify(e), 200));
  }
  if (resp.stop_reason !== 'end_turn') {
    const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
    return fail('claim-check-failed: stop_reason ' + JSON.stringify(resp.stop_reason) + why);
  }
  const text = (Array.isArray(resp.content) ? resp.content : [])
    .filter(function (b) { return b && b.type === 'text'; })
    .map(function (b) { return b.text; })
    .join('');
  let parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    parsed = null;
  }
  const list = parsed && Array.isArray(parsed.statements) ? parsed.statements : null;
  const wellFormed = list && list.every(function (s) {
    return s && typeof s === 'object' && typeof s.sentence === 'string' && typeof s.statement === 'string' &&
      typeof s.source === 'string' && typeof s.why === 'string' &&
      KINDS.indexOf(s.kind) !== -1 && VERDICTS.indexOf(s.verdict) !== -1;
  });
  if (!wellFormed) return fail('claim-check-failed: the answer was not the check schema: ' + excerpt(text, 120));
  rec.statements = list;

  const reasons = [];
  const cov = coverage(checkText(ctx.check), list);
  if (cov.foreign.length) {
    reasons.push('claim-check-incomplete: quoted text that is not in the email ("' + excerpt(cov.foreign[0], 60) + '")');
  }
  if (cov.left.length) {
    reasons.push('claim-check-incomplete: ' + cov.left.length + ' word' + (cov.left.length === 1 ? '' : 's') +
      ' never reviewed ("' + excerpt(cov.left.join(' '), 60) + '")');
  }
  if (ctx.kind === 'first-touch' && !list.some(function (s) { return s.kind === 'claim'; })) {
    reasons.push('claim-check-incomplete: no product claim found in a first email');
  }

  const ok = confirmedCodes(ctx);
  const problems = [];
  list.forEach(function (s) {
    const what = '"' + excerpt(s.statement || s.sentence) + '"';
    const src = apStr(s.source) ? ' (' + apStr(s.source) + ')' : '';
    if (s.kind === 'claim') {
      const codes = sourceCodes(s.source);
      if (s.verdict !== 'supported') {
        problems.push(s.verdict + ' ' + what + src);
      } else if (!codes.length || codes.some(function (c) { return ok.indexOf(c) === -1; })) {
        problems.push('no confirmed claim behind ' + what + src);
      }
    } else if (s.kind === 'prospect') {
      if (s.verdict !== 'supported') problems.push(s.verdict + ' fact ' + what + src);
    } else if (s.verdict !== 'none') {
      problems.push(s.verdict + ' ' + what + src);
    }
  });
  if (problems.length) reasons.push('claim-check: ' + problems.join('; '));

  rec.reasons = reasons;
  rec.result = reasons.length ? 'hold' : 'pass';
  return rec;
}

// ---------------------------------------------------------------------------
// The repair loop
// ---------------------------------------------------------------------------

// The workflows unroll exactly this many repair rounds; both builds refuse a
// different count.
const MAX_REPAIRS = 2;

// What a repair may fix: a statement the checker judged to say more than its
// source. A check that failed as a process (an HTTP error, a refusal, quotes
// that do not cover the email, a "supported" claim citing no confirmed code) is
// not a sentence the composer can rewrite, so it is held as it is.
const REPAIRABLE = ['widened', 'unsupported', 'joined'];

const REPAIR_SCHEMA = {
  type: 'object',
  properties: {
    rewrites: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          original: { type: 'string' },
          replacement: { type: 'string' },
        },
        required: ['original', 'replacement'],
        additionalProperties: false,
      },
    },
  },
  required: ['rewrites'],
  additionalProperties: false,
};

const REPAIR_SYSTEM_PROMPT = [
  'You repair one outbound sales email that an automatic claim check held. A small company sells a',
  'website assistant to contract research organisations (CROs). The check found sentences that say',
  'more than their sources support. Rewrite ONLY those sentences, so that each says no more than its',
  'source. Every other sentence stays exactly as it is -- you are not shown it to change it.',
  '',
  'You are given APPROVED CLAIMS (the only things the email may say about what we built, what it does,',
  'the problem it addresses, who uses it, and the offer), the PROSPECT RECORD (the only facts about the',
  'recipient), the email, and each flagged sentence with the checker\'s exact reason.',
  '',
  'For each flagged sentence:',
  '- Remove what the checker says goes beyond the source. Say what the approved claim says, in its own',
  '  words, rephrased only for grammar and to fit the sentence.',
  '- Add nothing: no new claim, fact, number, outcome, consequence or name. Shorter is better than',
  '  wider.',
  '- If nothing in the sentence can stay without the widening, make it the approved claim it rests on,',
  '  or return an empty replacement to delete the sentence.',
  '- Keep "(we call it Nova)" if the sentence has it. No greeting, no links.',
  '',
  'Return JSON: rewrites, one per flagged sentence -- "original" (the flagged sentence exactly as it is',
  'given to you) and "replacement".',
].join('\n');

// The flagged sentences, each with every reason the checker gave for it.
function flaggedSentences(statements) {
  const out = [];
  const byKey = {};
  (statements || []).forEach(function (s) {
    if (!s || REPAIRABLE.indexOf(s.verdict) === -1) return;
    const key = apWords(s.sentence).replace(/^subject /, '');
    if (!key) return;
    if (!byKey[key]) {
      byKey[key] = { sentence: apStr(s.sentence).replace(/^subject:\s*/i, ''), reasons: [] };
      out.push(byKey[key]);
    }
    byKey[key].reasons.push({ statement: apStr(s.statement), kind: s.kind, verdict: s.verdict,
      source: apStr(s.source), why: apStr(s.why) });
  });
  return out;
}

function repairPrompt(ctx, flagged) {
  const claims = (ctx.claims || []).filter(function (c) { return c && c.confirmed === true; });
  const subject = apStr(ctx.check && ctx.check.subject);
  const out = ['APPROVED CLAIMS:'].concat(claims.map(function (c) {
    return '  [' + apStr(c.code) + '] (' + apStr(c.slot) + ') ' + apStr(c.body);
  }), ['', 'PROSPECT RECORD:', apStr(ctx.record) || '(nothing is known about them)']);
  if (ctx.kind === 'follow-up' && apStr(ctx.first_email)) {
    out.push('', 'THE FIRST EMAIL, already sent to them -- context only:', '---', apStr(ctx.first_email), '---');
  }
  out.push('', 'THE EMAIL:');
  if (subject) out.push('Subject: ' + subject);
  out.push('---', apStr(ctx.check && ctx.check.text), '---', '', 'FLAGGED SENTENCES -- rewrite these, and only these:');
  flagged.forEach(function (f, i) {
    out.push(String(i + 1) + '. ' + f.sentence);
    f.reasons.forEach(function (r) {
      out.push('   checker: ' + r.verdict + ' -- "' + r.statement + '"' + (r.source ? ' (compared with ' + r.source + ')' : '') +
        ': ' + r.why);
    });
  });
  return out.join('\n');
}

// No cache_control here on purpose -- REPAIR_SYSTEM_PROMPT is 448 tokens, under
// the 512-token minimum (see the comment above checkRequest).
function repairRequest(ctx, flagged) {
  return {
    model: CHECK_MODEL,
    max_tokens: CHECK_MAX_TOKENS,
    output_config: { effort: CHECK_EFFORT, format: { type: 'json_schema', schema: REPAIR_SCHEMA } },
    system: REPAIR_SYSTEM_PROMPT,
    messages: [{ role: 'user', content: repairPrompt(ctx, flagged) }],
  };
}

// Where a quoted sentence sits in a field of the composition: compared word by
// word, folded the same way the coverage check folds, so curly quotes, case and
// accents do not stop a match. The span runs to the end of its trailing
// punctuation.
function tokenSpans(text) {
  const re = /[\p{L}\p{N}]+/gu;
  const out = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    out.push({ w: apWords(m[0]), s: m.index, e: m.index + m[0].length });
  }
  return out.filter(function (t) { return t.w; });
}

function locate(text, quote) {
  const q = apWords(quote).replace(/^subject /, '').split(' ').filter(Boolean);
  if (!q.length) return null;
  const t = tokenSpans(text);
  for (let i = 0; i + q.length <= t.length; i++) {
    let ok = true;
    for (let j = 0; j < q.length; j++) {
      if (t[i + j].w !== q[j]) { ok = false; break; }
    }
    if (ok) {
      let end = t[i + q.length - 1].e;
      while (end < text.length && !/\s/.test(text[end])) end++;
      return { s: t[i].s, e: end };
    }
  }
  return null;
}

// The model's rewrites, applied BY CODE to the fields the email's generated
// text came from. A rewrite whose original is not a flagged sentence is
// ignored, so a repair can change nothing the checker did not flag.
function applyRewrites(composition, fields, flagged, rewrites) {
  const out = JSON.parse(JSON.stringify(composition || {}));
  const keys = {};
  flagged.forEach(function (f) { keys[apWords(f.sentence)] = f; });
  const applied = [];
  const ignored = [];
  (rewrites || []).forEach(function (r) {
    const original = apStr(r && r.original).replace(/^subject:\s*/i, '');
    const replacement = apStr(r && r.replacement);
    const f = keys[apWords(original)];
    if (!f) {
      ignored.push({ original: original, why: 'not a flagged sentence' });
      return;
    }
    for (let i = 0; i < (fields || []).length; i++) {
      const field = fields[i];
      if (typeof out[field] !== 'string') continue;
      const at = locate(out[field], f.sentence);
      if (!at) continue;
      const before = out[field].slice(0, at.s);
      const after = out[field].slice(at.e);
      if (replacement) {
        out[field] = before + replacement + after;
      } else {
        // An empty replacement deletes the sentence, and the space beside it.
        const b = before.replace(/[ \t]+$/, '');
        const a = after.replace(/^[ \t]+/, '');
        out[field] = b + (b && a && !/\n$/.test(b) && !/^\n/.test(a) ? ' ' : '') + a;
      }
      applied.push({ field: field, original: f.sentence, replacement: replacement });
      delete keys[apWords(original)];
      return;
    }
    ignored.push({ original: original, why: 'not found in the email' });
  });
  const changed = applied.some(function (a) { return apWords(a.original) !== apWords(a.replacement); });
  return { composition: out, applied: applied, ignored: ignored, changed: changed };
}

// Every attempt's reasons, for hold_reason. One attempt reads as it always
// did; after repairs each attempt is labelled.
function attemptLabel(n) {
  return n === 1 ? 'first draft' : 'after repair ' + (n - 1);
}

function historyText(history) {
  const list = (history || []).filter(function (h) { return h && Array.isArray(h.reasons); });
  if (list.length === 1 && !list[0].repair_failed) return list[0].reasons.join('; ');
  return list.map(function (h) {
    return attemptLabel(h.attempt) + ': ' + h.reasons.join('; ') + (h.repair_failed ? '; repair ' + h.attempt + ' failed: ' + h.repair_failed : '');
  }).join(' | ');
}

// ---------------------------------------------------------------------------

// ===========================================================================
// Apply Repair -- n8n Code node (Run Once for Each Item).
//
// Shipped as code_approval.js above its "Node body" marker (the rules, verbatim)
// followed by this file, in Workflow 4 and in Follow-Ups alike, once per repair
// round. The build bakes in which Apply Claim Check copy this one follows.
//
// Reads that node's item -- a draft the claim check held, with the flagged
// sentences and the composition they came from -- and the Claude Repair
// node's answer: one rewrite per flagged sentence. The rewrites are applied BY
// CODE (applyRewrites), only to flagged sentences and only inside the fields
// the email's generated text came from, so a repair cannot touch anything the
// checker did not flag.
//
// The repaired composition leaves this node shaped like a model response, so
// the next node -- a second copy of the Assemble node, the same code -- runs
// every rule on it again, and the Approval Gate and the claim check run again
// after that. `repair` rides along with it, carrying the attempts so far.
//
// A repair that fails -- an HTTP error, a refusal, a cut-off, an answer that is
// not the schema, rewrites that change no flagged sentence -- ends the loop:
// the draft is held (repaired: false) with every reason so far, plus this one.
// ===========================================================================

// Node body

const prev = $('Apply Claim Check R1').item.json;
const resp = $input.item.json;
const st = prev.repair_state || {};
const ctx = prev.approval || {};

function hold(reason) {
  const payload = JSON.parse(JSON.stringify(prev.payload || {}));
  const d = draftsOf(payload)[st.target];
  const history = (st.history || []).slice();
  if (history.length) history[history.length - 1] = Object.assign({}, history[history.length - 1], { repair_failed: reason });
  if (d) {
    d.status = 'pending';
    d.approved_by = null;
    d.hold_reason = historyText(history);
    d.claim_check = Object.assign({}, d.claim_check || {}, {
      result: 'hold', repairs: history.length, attempts: history,
      repair_failed: { reason: reason, usage: resp && resp.usage ? resp.usage : null },
    });
  }
  return {
    json: Object.assign({}, prev, {
      repaired: false, payload: payload, needs_repair: false, repair_request: null, repair_state: null,
    }),
  };
}

if (!resp || typeof resp !== 'object') return hold('no response');
if (resp.error) {
  const e = resp.error;
  return hold(excerpt(typeof e === 'string' ? e : JSON.stringify(e), 200));
}
if (resp.stop_reason !== 'end_turn') {
  const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
  return hold('stop_reason ' + JSON.stringify(resp.stop_reason) + why);
}
const text = (Array.isArray(resp.content) ? resp.content : [])
  .filter(function (b) { return b && b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('');
let parsed = null;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}
const wellFormed = parsed && Array.isArray(parsed.rewrites) && parsed.rewrites.every(function (r) {
  return r && typeof r.original === 'string' && typeof r.replacement === 'string';
});
if (!wellFormed) return hold('the answer was not the repair schema: ' + excerpt(text, 120));
if (!st.composition || !Array.isArray(st.flagged)) return hold('no composition to repair');

const res = applyRewrites(st.composition, ctx.repair_fields || [], st.flagged, parsed.rewrites);
if (!res.changed) {
  return hold('the rewrites changed no flagged sentence' +
    (res.ignored.length ? ' (' + res.ignored.map(function (x) { return x.why; }).join(', ') + ')' : ''));
}

return {
  json: {
    repaired: true,
    model: resp.model,
    stop_reason: 'end_turn',
    stop_details: null,
    content: [{ type: 'text', text: JSON.stringify(res.composition) }],
    usage: null,
    repair: {
      round: (st.history || []).length,
      target: st.target,
      history: st.history || [],
      compose_usage: st.compose_usage || null,
      last_repair_usage: resp.usage || null,
      rewrites: res.applied,
      ignored: res.ignored,
    },
  },
};

// Assemble Follow-Up -- generated by n8n/sendtrack/build_workflow.py.
// Part 1, verbatim: n8n/drafting/code_assemble.js above its 'Node body' marker -- the
// first touch's claim rules. Part 2: n8n/sendtrack/code_followup_assemble.js.

// Assemble Drafts -- n8n Code node (Run Once for Each Item).
//
// Turns one Claude response into the two draft rows Section 9 asks for ("email
// variant + LinkedIn variant per lead into `drafts`"), and enforces every rule
// of NovaScout_DraftingSkill.md v3, section 3, that a string match can enforce.
//
// Skill v3 moved from verbatim line-picking to composition: Claude Sonnet 5.5
// writes the whole email -- subject, body and one ask -- from one prospect fact
// plus the approved claims Assess Grounding handed it. That makes this node the
// only thing standing between the model's prose and the review queue, so every
// rule the skill states as a rule is checked here, deterministically (build
// rule 3), on what actually came back:
//
//   length        body 70-110 words is the target; above 125 is tagged `long`
//   ask           exactly one: one question in the ask, no request in the body
//   links         none in warm-up weeks 1-2, then only the library's link line
//   product name  at most once, in brackets, never in the subject
//   "AI"          at most once, never in the subject, never "AI-powered"
//   sponsor       the prospect is never the one sponsoring ("You're sponsoring")
//   claims        no guarantee, no number the library and facts do not hold, no
//                 visitor identification, no named CRM or tool, no languages,
//                 never "chatbot", never that Nova books a call, never SOPs or
//                 client documents as its source; no two claim lines that
//                 repeat a capability
//   proof         the geography-matched deployment is named; no other one is
//   grounding     no therapeutic area the lead lacks; no founder or city opener;
//                 a trial is never credited to their website
//
// The opt-out sentence, the signature and the greeting are appended HERE, not
// generated. Section 5 locks the opt-out verbatim and makes it the whole basis
// for GDPR/KVKK legitimate interest.
//
// A violation tags the draft's `variant` rather than discarding it. The reviewer
// sees the tag next to the text; a silently dropped draft teaches nobody
// anything. Every draft still needs a human approval before Workflow 6 sends it.

// ---------------------------------------------------------------------------
// Locked constants. build_workflow.py parses each out of NovaScout_MasterRef.md
// or NovaScout_DraftingSkill.md and refuses to build on drift.
// ---------------------------------------------------------------------------

// Section 5, "Message rules -- LOCKED". Verbatim, including the straight
// apostrophes -- this string is the opt-out mechanism, not a paraphrase of it.
const OPT_OUT = "If this isn't relevant, reply 'no' and I won't follow up.";

// Skill v3 section 3, Length: "The body (everything above the opt-out line)
// should be 70-110 words and never more than 125." Counted over the body and
// the ask -- the greeting is the fixed frame, as in v2. Only the ceiling tags;
// "shorter is fine if nothing useful is lost".
const BODY_TARGET_MIN = 70;
const BODY_TARGET_MAX = 110;
const BODY_CEILING = 125;

// Section 5: "Maximum one plain URL. No buttons."
const MAX_URLS = 1;

// Master Ref Section 9, Workflow 4, Links: none in warm-up weeks 1-2. From week
// 3 the one URL Section 5 allows may appear -- and only the library's link
// line, appended here, never written by the model.
const LINK_FREE_WEEKS = 2;

// Skill v3 section 3, Subject: "30-55 characters ... Never the product name.
// Never 'AI'. No 'Re:', no 'Fwd:', no capitals."
const SUBJECT_MIN_CHARS = 30;
const SUBJECT_MAX_CHARS = 55;
const SUBJECT_REPLY_PREFIXES = ['re', 'fwd'];

// Skill v3 section 3, Naming the product: "The name appears at most once, in
// brackets". "The word 'AI' appears at most once".
const PRODUCT_NAME = 'Nova';
const PRODUCT_NAME_MAX = 1;
const AI_MAX = 1;

// Skill v3 section 3, Everywhere: "No banned adjectives (revolutionary,
// cutting-edge, innovative, game-changing, seamless)." The rest are the same
// register and fail the same way.
const BANNED_ADJECTIVES = [
  'revolutionary',
  'cutting-edge',
  'cutting edge',
  'innovative',
  'game-changing',
  'game changing',
  'seamless',
  'best-in-class',
  'world-class',
  'state-of-the-art',
  'leverage',
  'synergy',
  'unlock',
  'supercharge',
];

// The live deployments a proof line can name. Which of them this lead may hear
// about is decided by its proof pool (Assess Grounding, by country).
const DEPLOYMENTS = ['NoblePath', 'Vertex'];

// Skill v3 section 3, Claims, forbidden: "naming a specific CRM, tool or
// integration". Generic words ("your CRM", "a spreadsheet") are fine. Only
// names that are not also ordinary English words are listed, so a false
// positive costs a review tag, not a wrong one.
const NAMED_TOOLS = [
  'hubspot', 'salesforce', 'pipedrive', 'zoho', 'microsoft dynamics', 'dynamics 365', 'monday.com',
  'freshsales', 'freshworks', 'zendesk', 'google sheets', 'google sheet', 'airtable', 'slack',
  'microsoft teams', 'calendly', 'gmail', 'whatsapp', 'veeva', 'intercom', 'resend', 'mailchimp',
];

// Section 9, Workflow 4: "no merge-tag phrasing tells". The literal tags a
// template would leave behind ([First Name], {{company}}, <domain>).
const MERGE_TAG = /(\{\{[^}]*\}\})|(\[[A-Za-z][A-Za-z _-]{1,30}\])|(<[A-Za-z][A-Za-z _-]{1,30}>)/;

const URL_RE = /\b(?:https?:\/\/|www\.)[^\s<>()]+/gi;

// Skill v3 section 3, Hook: "Never describe the prospect as sponsoring anything
// ('You're sponsoring...' is banned)." Every way the v2 drafts and fact sheet
// put it.
const PROSPECT_SPONSOR = [
  /\byou(?:['’]re| are)\s+(?:also\s+|currently\s+|now\s+|actively\s+)?sponsor(?:ing|s)?\b/i,
  /\byou(?:['’]re| are)\s+(?:the|a|an)\s+(?:\w+\s+)?sponsor\b/i,
  /\byou\s+sponsor(?:ed|s)?\b/i,
  /\byou as (?:the |a )?sponsor\b/i,
  /\bsponsored by you\b/i,
  /\byour (?:own )?(?:sponsored|sponsorship)\b/i,
];

// Skill v3 section 3, Claims, forbidden. Each is a pattern for one rule.
const GUARANTEE = /\bguarantee\w*|\bnever (?:again )?(?:lose|miss)\b|\bno (?:lead|inquiry|inquiries|sponsor|sponsors) (?:is |are |gets |get |will be )?(?:ever )?(?:lost|missed)\b|\b100 ?%|\bwill (?:win|double|triple|increase|grow|boost)\b|\byou(?:['’]ll| will) (?:never|always|win|get more)\b|\b(?:ensures?|makes? sure) (?:you|that you) never\b/i;
const VISITOR_ID = /\b(?:identif\w*|reveal\w*|unmask\w*|de-?anonymi\w*|track\w*)\b[^.?!]{0,60}\b(?:visit\w*|visitors?|anonymous|traffic|browse\w*)\b|\banonymous (?:visitors?|traffic)\b|\b(?:see|know|tells? you|shows? you)\s+(?:exactly\s+)?(?:who|which \w+)\s+(?:visit\w*|browse\w*|land\w* on|came to)\b/i;
const LANGUAGES = /\bmulti-?lingual\b|\blanguages?\b|\b(?:turkish|spanish|arabic|german|french|portuguese|english|polish|romanian|hungarian|czech|hindi|urdu)\b/i;
const CHATBOT = /\bchat ?bots?\b|\bQ ?& ?A bots?\b/i;
const AI_POWERED = /\bAI[- ]?(?:powered|driven|based)\b/i;
// Settled 2026-10-02 against the Nova Agent Kit code (migration 013): Nova does
// not book -- it sends the booking link and the sponsor books through it -- and
// it answers from the CRO's website, never from SOPs or documents a client
// provides. "So they can book a call" is fine; Nova "books the call" is not.
const NOVA_BOOKS = /\bbooks\s+(?:the\s+|a\s+|qualified\s+|sponsor\s+)?(?:calls?|meetings?|demos?)\b|\b(?:into|onto|straight into)\s+your\s+(?:calendar|diary)\b|\bschedules\s+(?:the\s+|a\s+)?(?:calls?|meetings?)\b/i;
const SOP_SOURCE = /\bSOPs?\b|\bstandard operating procedures?\b|\b(?:your|their)\s+(?:own\s+)?(?:documents|documentation)\b/i;

// Skill v3 section 3, Claims: "any number, percentage or multiplier that is not
// in section 4". Digit tokens are checked against the library and the facts;
// these are the spelled-out numbers and multipliers a model reaches for. "one"
// is not here -- "one word back", "one question" are the skill's own words.
const NUMBER_WORDS = [
  'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'twenty',
  'thirty', 'fifty', 'hundred', 'hundreds', 'thousand', 'thousands', 'million', 'millions', 'billion',
  'dozen', 'dozens', 'double', 'doubles', 'doubled', 'triple', 'triples', 'tripled', 'twice', 'half',
  'percent', 'tenfold',
];
// A digit in the corpus licenses its word: the fact sheet says "2 recruiting
// trials", the model may write "two recruiting trials".
const DIGIT_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty'];

// Skill v3 section 3, Ask: "Exactly one ask. The reply costs one word. No
// links, no scheduling link, no '30-minute call'." The ask is its own field in
// the model's schema, so exactly one ask means: one question there, and no
// request anywhere in the body.
const REQUEST_IN_BODY = /\b(?:would you|could you|are you open|worth a (?:look|chat|call|try|conversation)|let me know|reply (?:yes|no|with|to)|one word back|shall i|should i|want me to|happy to (?:set|send|show|share|walk)|interested in (?:a|seeing|trying|hearing)|open to a|up for a|free for a)\b/i;
const ASK_SCHEDULING = /\b\d+[- ]?min(?:ute)?s?\b|\b(?:fifteen|twenty|thirty)[- ]minutes?\b|\bcalendly\b|\bschedul\w*|\bbook (?:a |some )?(?:time|slot|call|meeting)\b|\b(?:time|slot)s? (?:that )?works?\b/i;

// Skill v3 section 3, Hook: "Never open on the founder's name or the city."
// And the trial fact is on ClinicalTrials.gov, not on their site.
const HOOK_SOURCE_OPENING = /^\s*(clinicaltrials\.gov|according to)\b/i;
const SITE_CLAIM = /\b(your|their|the)\s+(web\s?)?site\b/i;
const TRIAL_WORD = /\b(trials?|stud(y|ies))\b/i;

// Acronyms a subject may carry in capitals.
const SUBJECT_ACRONYMS = ['CRO', 'CROS', 'BD'];

// The order claim codes are recorded in `variant`.
const SLOT_ORDER = ['description', 'angle', 'benefit', 'proof', 'ask', 'link'];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// A word is a token with a letter or a digit in it. A dash between clauses is
// punctuation, not a word.
function words(v) {
  const t = str(v);
  return t ? t.split(/\s+/).filter(function (w) { return /[\p{L}\p{N}]/u.test(w); }).length : 0;
}

function fold(v) {
  return str(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// A model that ignores "no greeting, no sign-off" produces a duplicate greeting
// once we prepend our own, and a sign-off that collides with the signature.
// Both are deterministic to strip.
const SIGNOFFS = [
  'best regards', 'kind regards', 'warm regards', 'best wishes', 'regards',
  'best', 'thanks', 'thank you', 'cheers', 'sincerely', 'yours sincerely',
];

function stripGreeting(body, greeting) {
  let out = str(body);
  const g = str(greeting).replace(/[,\s]+$/, '');
  // The trailing comma or colon is REQUIRED: optional, this ate the start of any
  // body that merely began with "Hi" or "Hello".
  out = out.replace(/^\s*(hi|hello|hey|dear|greetings)\b[^\n,]{0,40}[,:]\s*\n?/i, '');
  if (g && out.toLowerCase().indexOf(g.toLowerCase()) === 0) {
    out = out.slice(g.length).replace(/^[,\s]+/, '');
  }
  return out.trim();
}

function stripSignoff(body) {
  const lines = str(body).split('\n');
  while (lines.length) {
    const last = lines[lines.length - 1].trim().toLowerCase().replace(/[,.!]+$/, '');
    if (!last) { lines.pop(); continue; }
    if (SIGNOFFS.indexOf(last) !== -1 || (lines.length > 1 && /^[a-z]{2,20}$/.test(last))) {
      lines.pop();
      continue;
    }
    break;
  }
  return lines.join('\n').trim();
}

// Paragraphs as the model wrote them, blank-line separated, inner whitespace
// tidied; never more than one blank line in a row.
function cleanText(raw, greeting) {
  return stripSignoff(stripGreeting(raw, greeting))
    .split(/\n\s*\n/)
    .map(function (p) { return p.replace(/\s*\n\s*/g, ' ').trim(); })
    .filter(Boolean)
    .join('\n\n');
}

function urlsIn(v) {
  return str(v).match(URL_RE) || [];
}

function bannedAdjectivesIn(v) {
  const t = ' ' + str(v).toLowerCase() + ' ';
  return BANNED_ADJECTIVES.filter(function (a) { return t.indexOf(a) !== -1; });
}

// Trial titles are quoted from ClinicalTrials.gov and can hold anything -- a
// digit, a question mark, a therapeutic area. The checks judge what the model
// wrote around a title, not the title it was given.
function withoutTitles(text, titles) {
  let out = str(text);
  for (const t of titles || []) {
    const title = str(t);
    if (!title) continue;
    let at = out.toLowerCase().indexOf(title.toLowerCase());
    while (at !== -1) {
      out = out.slice(0, at) + ' ' + out.slice(at + title.length);
      at = out.toLowerCase().indexOf(title.toLowerCase());
    }
  }
  return out;
}

function digitTokens(v) {
  return (str(v).match(/[\p{L}\p{N}]*\p{N}[\p{L}\p{N}]*/gu) || []).map(function (t) { return t.toLowerCase(); });
}

// Numbers the text states that the corpus (this lead's facts plus every claim it
// was offered) does not: a digit token, a spelled-out number or multiplier, or a
// percent sign.
function unlicensedNumbers(text, corpus) {
  const haveDigits = {};
  digitTokens(corpus).forEach(function (t) { haveDigits[t] = true; });
  const bad = digitTokens(text).filter(function (t) { return !haveDigits[t]; });
  let corpusWords = ' ' + fold(corpus).replace(/[^a-z0-9]+/g, ' ') + ' ';
  Object.keys(haveDigits).forEach(function (t) {
    if (/^\d+$/.test(t) && Number(t) < DIGIT_WORDS.length) corpusWords += DIGIT_WORDS[Number(t)] + ' ';
  });
  const textWords = fold(text).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean);
  textWords.forEach(function (w) {
    if (NUMBER_WORDS.indexOf(w) !== -1 && corpusWords.indexOf(' ' + w + ' ') === -1) bad.push(w);
  });
  if (str(text).indexOf('%') !== -1 && str(corpus).indexOf('%') === -1) bad.push('%');
  return bad;
}

function absentAreasNamed(text, absentAreas) {
  const plain = ' ' + fold(text).replace(/[^a-z0-9]+/g, ' ') + ' ';
  return (absentAreas || []).filter(function (a) {
    return plain.indexOf(' ' + fold(a).replace(/[^a-z0-9]+/g, ' ') + ' ') !== -1;
  });
}

// Does the text open on this name (or its first word)? Plain string compare.
function startsWithName(text, name) {
  const t = fold(text);
  const n = fold(name);
  if (!n) return false;
  const first = n.split(/\s+/)[0];
  const opensOn = function (w) {
    return t.indexOf(w) === 0 && (t.length === w.length || !/[a-z0-9]/.test(t.charAt(w.length)));
  };
  return opensOn(n) || (first.length >= 3 && opensOn(first));
}

function firstSentence(text) {
  const m = str(text).match(/^[\s\S]*?[.!?](?=\s|$)/);
  return m ? m[0] : str(text);
}

function countOf(re, text) {
  return (str(text).match(new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags)) || []).length;
}

// ---------------------------------------------------------------------------
// The rule checks. Each returns the tags it found; checkMessage runs them all.
// ---------------------------------------------------------------------------

// "Exactly one ask."
function askFlags(body, ask) {
  const flags = [];
  const q = countOf(/\?/, ask);
  if (!str(ask) || q === 0) flags.push('ask-none');
  if (q > 1 || REQUEST_IN_BODY.test(body)) flags.push('ask-multiple');
  if (ASK_SCHEDULING.test(ask)) flags.push('ask-scheduling');
  return flags;
}

// "The name appears at most once, in brackets." Stripping every bracketed
// segment leaves nothing that may still say the name.
function productFlags(text) {
  const flags = [];
  const name = new RegExp('\\b' + PRODUCT_NAME + '\\b', 'gi');
  const n = countOf(name, text);
  if (n > PRODUCT_NAME_MAX) flags.push('product-name-repeat');
  const unbracketed = str(text).replace(/\([^()]*\)/g, ' ');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(unbracketed)) flags.push('product-name-unbracketed');
  return flags;
}

// "The word 'AI' appears at most once ... Never 'AI-powered'."
function aiFlags(text) {
  const flags = [];
  if (countOf(/\bA\.?I\b\.?/, text) > AI_MAX) flags.push('ai-repeat');
  if (AI_POWERED.test(text)) flags.push('ai-powered');
  return flags;
}

function prospectSponsor(text) {
  return PROSPECT_SPONSOR.some(function (re) { return re.test(text); });
}

// Skill v3 section 3, Claims, forbidden.
function claimFlags(text, corpus) {
  const flags = [];
  if (GUARANTEE.test(text)) flags.push('claim-guarantee');
  if (unlicensedNumbers(text, corpus).length) flags.push('claim-number');
  if (VISITOR_ID.test(text)) flags.push('claim-visitor-id');
  const t = ' ' + fold(text) + ' ';
  if (NAMED_TOOLS.some(function (n) { return new RegExp('(^|[^a-z0-9])' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(t); })) {
    flags.push('claim-named-tool');
  }
  if (LANGUAGES.test(text)) flags.push('claim-language');
  if (CHATBOT.test(text)) flags.push('claim-chatbot');
  if (NOVA_BOOKS.test(text)) flags.push('claim-books');
  if (SOP_SOURCE.test(text)) flags.push('claim-sop');
  return flags;
}

// Skill v3 section 3, No repeats: "The description and the benefits must not
// repeat the same capability." Each description and benefit line names its
// capabilities (claims_library.capabilities, migration 013); two codes one
// message used that share one say the same thing twice. `capsOf(code)` returns
// a code's capabilities (none for an angle, proof or ask).
function repeatFlags(codes, capsOf) {
  const flags = [];
  const seen = {};
  let repeated = false;
  for (const code of codes || []) {
    for (const cap of capsOf(code) || []) {
      if (seen[cap] && seen[cap] !== code) repeated = true;
      seen[cap] = code;
    }
  }
  if (repeated) flags.push('claim-repeat');
  return flags;
}

// "Proof: one named live deployment, matched to the lead's geography."
function proofFlags(text, proofPool) {
  const flags = [];
  const pool = proofPool || [];
  const allowed = DEPLOYMENTS.filter(function (d) {
    return pool.some(function (p) { return fold(p.body).indexOf(fold(d)) !== -1; });
  });
  const both = pool.some(function (p) { return /\btwo CROs\b/i.test(p.body); });
  const named = DEPLOYMENTS.filter(function (d) { return fold(text).indexOf(fold(d)) !== -1; });
  if (named.some(function (d) { return allowed.indexOf(d) === -1; })) flags.push('proof-geo');
  const present = named.some(function (d) { return allowed.indexOf(d) !== -1; }) ||
    (both && /\btwo (?:CROs|CRO clients|clients)\b/i.test(text));
  if (!present) flags.push('proof-missing');
  return flags;
}

// The first sentence opens on the prospect fact. Section 9 Workflow 4:
// founder_name and city never open a message; a trial is never credited to
// their website.
function hookFlags(hook, src, titles) {
  const flags = [];
  if (startsWithName(hook, src.founder_name) || startsWithName(hook, src.city)) flags.push('hook-opener');
  const own = withoutTitles(hook, titles);
  const titlesNamed = (titles || []).filter(function (t) {
    return str(t) && hook.toLowerCase().indexOf(str(t).toLowerCase()) !== -1;
  }).length;
  const trialOnSite = SITE_CLAIM.test(own) && (titlesNamed > 0 || TRIAL_WORD.test(own));
  if (HOOK_SOURCE_OPENING.test(hook) || trialOnSite) flags.push('hook-source');
  return flags;
}

function linkFlags(text, week, approvedLink) {
  const flags = [];
  const urls = urlsIn(text);
  if (urls.length > MAX_URLS) flags.push('urls');
  if (urls.length && week <= LINK_FREE_WEEKS) flags.push('link-in-warmup');
  const approved = approvedLink ? urlsIn(approvedLink.body) : [];
  if (urls.some(function (u) { return approved.indexOf(u) === -1; })) flags.push('unapproved-link');
  if (urls.some(function (u) { return /linkedin\.com/i.test(u); })) flags.push('linkedin-link');
  if (urls.some(function (u) { return /\.pdf\b/i.test(u); })) flags.push('pdf-link');
  return flags;
}

function subjectFlags(subject, factCorpus, headcount, titles, absentAreas) {
  const flags = [];
  const chars = Array.from(subject).length;
  if (!subject || chars < SUBJECT_MIN_CHARS || chars > SUBJECT_MAX_CHARS) flags.push('subject');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(subject)) flags.push('subject-product');
  if (/\bA\.?I\b/i.test(subject)) flags.push('subject-ai');
  const prefix = new RegExp('\\b(' + SUBJECT_REPLY_PREFIXES.join('|') + ')\\s*:', 'i');
  if (prefix.test(subject)) flags.push('subject-reply');
  // "No capitals": sentence case. A capitalised word after the first is allowed
  // only when the facts spell it that way (a trial code, a city) or it is an
  // acronym a CRO uses.
  const corpusWords = {};
  (factCorpus.match(/[\p{L}\p{N}-]+/gu) || []).forEach(function (t) { corpusWords[t] = true; });
  const tokens = subject.match(/[\p{L}\p{N}-]+/gu) || [];
  const capped = tokens.filter(function (t, i) {
    if (!/\p{Lu}/u.test(t)) return false;
    if (i === 0 && !/^\p{Lu}{2,}$/u.test(t)) return false;
    return !corpusWords[t] && SUBJECT_ACRONYMS.indexOf(t.toUpperCase()) === -1;
  });
  if (capped.length) flags.push('subject-caps');
  const corpus = factCorpus + (headcount ? ' ' + headcount : '');
  const bare = withoutTitles(subject, titles);
  if (digitTokens(bare).some(function (t) { return digitTokens(corpus).indexOf(t) === -1; }) ||
      absentAreasNamed(bare, absentAreas).length) {
    flags.push('subject-ungrounded');
  }
  return flags;
}

// Sites and SMOs, 2026-10-09 (Section 9, Workflow 4; operator instruction).
// Vertex Clinical Research is a clinical research center and is never called a
// CRO, whoever the email is to (`vertex-cro`). And a research site or an SMO is
// never told about "CRO websites" (`cro-website`), never given the "two CROs"
// proof (`proof-two-cros`), and never called a CRO itself (`prospect-cro`) --
// "CROs choosing sites" is how a site hears from a CRO, so naming CROs as the
// site's visitors is allowed and is not tagged.
const VERTEX_AS_CRO = /\bVertex\b[^.?!]{0,60}\bCROs?\b|\bCROs?\b[^.?!]{0,30}\bVertex\b/i;
const CRO_WEBSITE = /\bCROs?(?:['’]s?)?\s+(?:web\s?)?sites?\b|\bCRO[- ]websites?\b/i;
const TWO_CROS = /\btwo CROs?\b/i;
const PROSPECT_CRO = /\b(?:you(?:['’]re| are)(?: a| an)?|your(?: own)?|as an?)\s+(?:small\s+|mid-sized\s+|independent\s+|local\s+)?CROs?\b/i;
function siteFlags(text, companyType) {
  const flags = [];
  if (VERTEX_AS_CRO.test(text)) flags.push('vertex-cro');
  if (companyType !== 'site' && companyType !== 'SMO') return flags;
  if (CRO_WEBSITE.test(text)) flags.push('cro-website');
  if (TWO_CROS.test(text)) flags.push('proof-two-cros');
  if (PROSPECT_CRO.test(text)) flags.push('prospect-cro');
  return flags;
}

// Every rule that applies to a message body, either channel.
function checkMessage(m) {
  let flags = [];
  if (!str(m.body)) flags.push('empty');
  if (words(m.core) > BODY_CEILING) flags.push('long');
  if (bannedAdjectivesIn(m.core).length) flags.push('adjective');
  if (MERGE_TAG.test(m.core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(m.body, m.ask));
  flags = flags.concat(productFlags(m.core));
  flags = flags.concat(aiFlags(m.core));
  if (prospectSponsor(m.core)) flags.push('prospect-sponsor');
  const own = withoutTitles(m.core, m.titles);
  flags = flags.concat(claimFlags(own, m.corpus));
  if (absentAreasNamed(own, m.absentAreas).length) flags.push('ungrounded-area');
  if (str(m.body)) flags = flags.concat(hookFlags(firstSentence(m.body), m.src, m.titles));
  flags = flags.concat(proofFlags(m.core, m.proofPool));
  flags = flags.concat(siteFlags(m.core, m.companyType));
  return flags;
}

function unique(list) {
  return list.filter(function (v, i) { return list.indexOf(v) === i; });
}

// Word-set overlap, for attributing an ask the model did not code to the library
// line it paraphrased. Also used by the follow-ups (Workflow 6), which embed
// everything above "Node body" verbatim.
function wordSet(v) {
  const set = {};
  fold(v).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean).forEach(function (w) { set[w] = true; });
  return set;
}
function jaccard(a, b) {
  const A = wordSet(a);
  const B = wordSet(b);
  const keys = unique(Object.keys(A).concat(Object.keys(B)));
  const both = keys.filter(function (k) { return A[k] && B[k]; }).length;
  return keys.length ? both / keys.length : 0;
}

